def group_words_by_length(words):
    """
    Returns a dictionary where the keys are the lengths of the words,
    and the values are lists of words of that length, sorted alphabetically.
    """
    from collections import defaultdict

    length_dict = defaultdict(list)
    for word in words:
        length_dict[len(word)].append(word)

    # Sort each list of words alphabetically
    for length in length_dict:
        length_dict[length].sort()

    return dict(length_dict)

