def max_even_sum_subarray_length(N, cards):
    """
    This function returns the maximum length of a contiguous subarray with even sum.
    """
    total_sum = sum(cards)

    if total_sum % 2 == 0:
        return N

    first_odd_index = -1
    last_odd_index = -1

    for i in range(N):
        if cards[i] % 2 != 0:
            if first_odd_index == -1:
                first_odd_index = i
            last_odd_index = i

    if first_odd_index == -1:
        return 0

    max_length_excluding_first_odd = N - first_odd_index - 1
    max_length_excluding_last_odd = last_odd_index

    return max(max_length_excluding_first_odd, max_length_excluding_last_odd)

