def removeDuplicates(s: str) -> str:
    """
    Repeatedly remove adjacent duplicates from the string until no such duplicates exist.
    """
    stack = []
    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)
    return ''.join(stack)

