def isIsomorphic(s, t):
    """
    Check if two strings s and t are isomorphic.
    """

    if len(s) != len(t):
        return False

    s_to_t_mapping = {}
    t_to_s_mapping = {}

    for char_s, char_t in zip(s, t):
        if char_s in s_to_t_mapping:
            if s_to_t_mapping[char_s] != char_t:
                return False
        else:
