def minimum_bonuses(n, ratings):
    if n == 1:
        return 1

    bonuses = [1] * n

    # Left to right pass
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            bonuses[i] = bonuses[i - 1] + 1

    # Right to left pass
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            bonuses[i] = max(bonuses[i], bonuses[i + 1] + 1)

    return sum(bonuses)

