def snake_pattern(n, arr):
    """
    This function transforms the given array into a snake pattern:
    - arr[i] <= arr[i + 1], if i is even
    - arr[i] >= arr[i + 1], if i is odd
    """
    for i in range(n - 1):
        if i % 2 == 0:
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
        else:
            if arr[i] < arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
    return arr

