def count_pairs_with_sum(nums, target):
    """
    Returns the number of unique pairs (i, j) where i < j and nums[i] + nums[j] equals the target.
    """
    count = 0
    seen = set()

    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target and (i, j) not in seen:
                count += 1
                seen.add((i, j))

    return count

def lexicographically_smallest_string(s, k):
    """
    Returns the lexicographically smallest string possible after exactly k operations.
    An operation consists of taking any character and moving it to the end of the string.

    :param s: input string
    :param k: number of operations
    :return: resulting string
    """
    if k == 1:
        # When k is 1, the optimal solution is achieved by finding the smallest rotation
        smallest = s
        for i in range(1, len(s)):
            rotated = s[i:] + s[:i]
            if rotated < smallest:
                smallest = rotated
        return smallest
    else:
        # When k >= 2, any permutation can be achieved, so we sort the string
        return "".join(sorted(s))

