def min_flips_to_no_adjacent_heads(n, coins):
    """
    Given the number of coins and their initial states, return the minimum number of flips required
    so that no two adjacent coins show heads.
    """
    flips = 0

    for i in range(1, n):
        if coins[i] == 'H' and coins[i - 1] == 'H':
            flips += 1
            if i % 2 == 1:
                coins = coins[:i] + 'T' + coins[i + 1:]
            else:
                coins = coins[:i - 1] + 'T' + coins[i:]

    return flips

