import itertools

def smallest_number_not_formable(N, numbers):
    """
    Returns the smallest positive integer that cannot be formed using 
    concatenated digits of the given list of integers when combined with + operation.
    """
    all_numbers = {0}

    digits_list = [str(num) for num in numbers]

    for i in range(1, N+1):
        for combination in itertools.permutations(digits_list, i):
            formed_num = int(''.join(combination))
            new_combinations = set()
            for existing_num in all_numbers:
                new_combinations.add(existing_num + formed_num)
            all_numbers.update(new_combinations)

    smallest_positive = 1
    while smallest_positive in all_numbers:
        smallest_positive += 1

    return smallest_positive

