    seen = set()
    unique_pairs = set()

    for i in range(len(arr)):
        complement = k - arr[i]
        if complement in seen:
            pair = tuple(sorted((arr[i], complement)))
            unique_pairs.add(pair)
        seen.add(arr[i])

    return len(unique_pairs)

from typing import List

def house_robber(houses: List[int]) -> int:
    if not houses:
        return 0

    n = len(houses)
    if n == 1:
        return houses[0]

    prev1, prev2 = 0, 0

    for money in houses:
        current = max(prev1, prev2 + money)
        prev2 = prev1
        prev1 = current

    return prev1

