def is_one_edit_distance(s, t):
    """
    Returns whether t can be generated from s by exactly one edit operation.
    """

    len_s, len_t = len(s), len(t)

    if abs(len_s - len_t) > 1:
        return "NO"

    # Ensure s is the shorter one
    if len_s > len_t:
        s, t = t, s
        len_s, len_t = len_t, len_s

    found_difference = False

    i, j = 0, 0
    while i < len_s and j < len_t:
        if s[i] != t[j]:
            if found_difference:
                return "NO"
            found_difference = True

            # If lengths are different, move pointer in the longer string
            if len_s < len_t:
                j += 1
            else:
                i += 1
                j += 1
        else:
            i += 1
            j += 1

    return "YES" if found_difference or len_s < len_t else "NO"

