def traverse_grid(instructions):
    """
    Returns the final coordinates after following the sequence of instructions.

    Args:
    instructions (str): sequence of 'U', 'D', 'L', 'R' representing moves on a 2D grid.

    Returns:
    tuple: final coordinates (x, y) after following all the instructions.
    """
    x, y = 0, 0

    for instr in instructions:
        if instr == 'U':
            y += 1
        elif instr == 'D':
            y -= 1
        elif instr == 'L':
            x -= 1
        elif instr == 'R':
            x += 1

    return (x, y)

