def min_removal_to_avoid_consecutive_duplicates(s):
    n = len(s)

    # Check if string already meets the requirement
    if all(s[i] != s[i + 1] for i in range(n - 1)):
        return 0

    # Try to find the minimum length substring to remove
    for length in range(1, n):
        for i in range(n - length + 1):
            new_s = s[:i] + s[i + length:]
            if all(new_s[j] != new_s[j + 1] for j in range(len(new_s) - 1)):
                return length

    # If no valid removal found, return -1
    return -1

