def subarray_sum(nums, target):
    """
    Returns the number of subarrays where the sum of elements is exactly `target`.
    """
    count = 0
    current_sum = 0
    prefix_sums = {0: 1}

    for num in nums:
        current_sum += num
        if current_sum - target in prefix_sums:
            count += prefix_sums[current_sum - target]
        if current_sum in prefix_sums:
            prefix_sums[current_sum] += 1
        else:
            prefix_sums[current_sum] = 1

    return count

