def is_permutation(str1, str2):
    """
    Checks if one string is a permutation of the other.
    """
    # If the lengths are different, they cannot be permutations of each other.
    if len(str1) != len(str2):
        return False

    # Sort both strings and compare them.
    return sorted(str1) == sorted(str2)

def find_first_activity_repeated_k_times(T, test_cases):
    results = []
    for i in range(T):
        N, K = test_cases[i][0]
        activities = test_cases[i][1]

        activity_count = {}

        for activity in activities:
            if activity in activity_count:
                activity_count[activity] += 1
            else:
                activity_count[activity] = 1

            if activity_count[activity] == K:
                results.append(activity)
                break
        else:
            results.append(-1)
    return results

