def max_consecutive_ones(binary_string):
    """
    Returns the maximum number of consecutive 1s obtainable by at most one flip 
    operation on any substring of the binary string.
    """

    n = len(binary_string)
    if n == 0:
        return 0

    left_ones = [0] * n
    right_ones = [0] * n

    current_ones = 0
    for i in range(n):
        if binary_string[i] == '1':
            current_ones += 1
        else:
            current_ones = 0
        left_ones[i] = current_ones

    current_ones = 0
    for i in range(n-1, -1, -1):
        if binary_string[i] == '1':
            current_ones += 1
        else:
            current_ones = 0
        right_ones[i] = current_ones

    max_consecutive_1s = max(left_ones) # Without any flip

    for i in range(1, n - 1):
        if binary_string[i] == '0':
            # Sequence if flipped binary_string[i] from 0 to 1
            max_consecutive_1s = max(max_consecutive_1s, left_ones[i-1] + 1 + right_ones[i+1])

    if '0' in binary_string:
        max_consecutive_1s = max(max_consecutive_1s, max(left_ones) + 1) # Single flip for all zeroes

    return max_consecutive_1s

