def max_bulbs_on_after_flip(arr):
    """
    This function calculates the maximum number of bulbs that can be turned on after exactly one 
    flip operation on any continuous subarray.
    """
    n = len(arr)
    total_ones = sum(arr)

    max_diff = 0
    current_diff = 0

    for i in range(n):
        if arr[i] == 1:
            current_diff -= 1
        else:
            current_diff += 1

        if current_diff < 0:
            current_diff = 0

        max_diff = max(max_diff, current_diff)

    if total_ones == n:
        return total_ones - 1

    return total_ones + max_diff

