def seating_arrangement(r, c):
    if r == 1 or c == 1:
        return "IMPOSSIBLE"

    result = [[0]*c for _ in range(r)]

    num = 1
    for i in range(r):
        for j in range(c):
            result[i][j] = num
            num += 1

    transposed = [[0]*r for _ in range(c)]

    for i in range(r):
        for j in range(c):
            transposed[j][i] = result[i][j]

    if r == c:
        if r <= 2:
            return "IMPOSSIBLE"
        else:
            return ["POSSIBLE"] + [transposed[i] for i in range(r)]

    return ["POSSIBLE"] + [list(row) for row in transposed]

