def replace_question_marks(s: str) -> str:
    """
    Replaces every '?' in the string s with a lowercase letter such that no two adjacent
    characters are the same. If there are multiple valid solutions, it returns any one of them.
    """
    n = len(s)
    s = list(s)  # Convert the string to a list for easier manipulation
    for i in range(n):
        if s[i] == '?':
            for char in 'abc':  # Check a, b, c to replace
                if (i > 0 and s[i - 1] == char) or (i < n - 1 and s[i + 1] == char):
                    continue
                s[i] = char
                break
    return "".join(s)

