import itertools

def min_distance(n, m, paths):
    # create a distance matrix for the nodes
    matrix = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        matrix[i][i] = 0

    # fill the distance matrix with the given paths
    for a, b, c in paths:
        matrix[a-1][b-1] = c
        matrix[b-1][a-1] = c

    # use Floyd-Warshall algorithm to find the shortest path between all pairs of nodes
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if matrix[i][j] > matrix[i][k] + matrix[k][j]:
                    matrix[i][j] = matrix[i][k] + matrix[k][j]

    # find the minimum path that visits all nodes using permutations
    nodes = range(1, n)
    min_path = float('inf')
    for perm in itertools.permutations(nodes):
        current_path = matrix[0][perm[0]]  # from node 1 to first node in permutation
        for i in range(len(perm) - 1):
            current_path += matrix[perm[i]][perm[i+1]]
        current_path += matrix[perm[-1]][0]  # back to node 1 from last node in permutation
        if current_path < min_path:
            min_path = current_path

    return min_path

