def min_candies(ratings):
    """
    Calculate the minimum number of candies required for the given
    ratings list such that each individual gets at least one candy
    and individuals with higher ratings get more candies than their neighbors.
    """
    n = len(ratings)
    candies = [1] * n

    # First pass: Scan from left to right
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            candies[i] = candies[i - 1] + 1

    # Second pass: Scan from right to left
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            candies[i] = max(candies[i], candies[i + 1] + 1)

    return sum(candies)

