from typing import List

def findSubarrays(nums: List[int], target: int) -> List[List[int]]:
    """
    Returns all contiguous subarrays whose sum equals the target value.
    """
    result = []

    for start in range(len(nums)):
        current_sum = 0
        for end in range(start, len(nums)):
            current_sum += nums[end]
            if current_sum == target:
                result.append(nums[start:end+1])

    return result

from typing import List

def find_three_sum(nums: List[int], target: int) -> List[int]:
    nums.sort()
    n = len(nums)
    for i in range(n):
        if i > 0 and nums[i] == nums[i-1]:
            continue
        left, right = i+1, n-1
        while left < right:
            s = nums[i] + nums[left] + nums[right]
            if s == target:
                return [nums[i], nums[left], nums[right]]
            elif s < target:
                left += 1
            else:
                right -= 1
    return []

