def can_be_palindrome(s):
    """
    Determine if the string `s` can be converted into a palindrome by changing 
    at most two characters.
    """
    n = len(s)
    mismatch_count = 0

    for i in range(n//2):
        if s[i] != s[n-i-1]:
            mismatch_count += 1
            if mismatch_count > 2:
                return "NO"

    return "YES"

