    If a word contains multiple symbols, the longest one is selected.
    """
    # Sort the symbols list by the length of the symbols in descending order
    symbols.sort(key=len, reverse=True)

    updated_words = []

    for word in words:
        longest_symbol = ""
        for symbol in symbols:
            if symbol in word:
                if len(symbol) > len(longest_symbol):
                    longest_symbol = symbol

        if longest_symbol:
            word = word.replace(longest_symbol, f'[{longest_symbol}]', 1)

        updated_words.append(word)

    return updated_words

