def longest_chain(n, strings):
    # Sort strings by length in descending order
    strings.sort(key=len, reverse=True)

    max_chain_length = dict()  # Keep track of max chain length that ends with each string

    for string in strings:
        max_chain_length[string] = 1  # Each string is at least a chain of 1

    for current in strings:
        for candidate in strings:
            if candidate == current:
                continue
            # Check if candidate is a suffix of the current string
            if current.endswith(candidate):
                max_chain_length[candidate] = max(max_chain_length[candidate], max_chain_length[current] + 1)

    # The result is the maximum value in the dictionary
    return max(max_chain_length.values())

