def optimized_hailstone(n):
    """
    Return the length of the hailstone sequence and the maximum value in the sequence
    n: The starting point of the hailstone sequence
    """

    sequence_length = 0
    max_value = n

    while n > 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        sequence_length += 1
        if n > max_value:
            max_value = n

    return (sequence_length + 1, max_value)  # Including the starting number

