def two_sum(nums, target):
    """
    Given a sorted array nums and a target, find the indices of two numbers such that they add up to the target.
    """
    left, right = 0, len(nums) - 1

    while left < right:
        current_sum = nums[left] + nums[right]
        if current_sum == target:
            return [left, right]
        elif current_sum < target:
            left += 1
        else:
            right -= 1

    # If no solution is found (the problem guarantees exactly one solution, so this line should never be hit)
    return []

