def partition_labels(s):
    """
    Given a string s consisting of lowercase English letters, divide the string into as many parts as possible 
    such that each letter appears in at most one part. Return a list of integers representing the lengths of these
    parts in order. The division must maximize the number of parts. Each part must be a contiguous substring of s.
    """
    last_occurrence = {char: idx for idx, char in enumerate(s)}
    partitions = []
    size, end = 0, 0

    for idx, char in enumerate(s):
        size += 1
        end = max(end, last_occurrence[char])

        if idx == end:
            partitions.append(size)
            size = 0

    return partitions

