def minimum_subgroups(n, target, sizes):
    """
    Returns the minimum number of subgroups required to store all files 
    without exceeding the target size in any subgroup.
    """
    sizes.sort(reverse=True)
    subgroups = []

    for size in sizes:
        placed = False
        for subgroup in subgroups:
            if sum(subgroup) + size <= target:
                subgroup.append(size)
                placed = True
                break
        if not placed:
            subgroups.append([size])

    return len(subgroups)

