def longest_contiguous_subarray(nums):
    """
    Returns the length of the longest contiguous subarray where every element
    is either strictly increasing or strictly decreasing.
    """
    if len(nums) < 2:
        return 0

    max_len = 1
    current_len = 1
    is_increasing = None

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            if is_increasing is None or is_increasing:
                current_len += 1
            else:
                current_len = 2
            is_increasing = True
        elif nums[i] < nums[i - 1]:
            if is_increasing is None or not is_increasing:
                current_len += 1
            else:
                current_len = 2
            is_increasing = False
        else:
            current_len = 1
            is_increasing = None

        max_len = max(max_len, current_len)

    return max_len

