def min_contiguous_subarrays_to_sort(arr):
    """
    Returns the minimum number of contiguous subarrays required to be sorted 
    so that the entire array, when concatenated back, becomes sorted in non-decreasing order.
    """
    n = len(arr)
    if n <= 1:
        return 1

    count = 1

    for i in range(1, n):
        if arr[i] < arr[i - 1]:
            count += 1

    return count

