def largest_lexicographical_permutation(n, k, arr):
    pos = {value: i for i, value in enumerate(arr)}

    for i in range(n):
        if k == 0:
            break
        max_value = n - i
        if arr[i] == max_value:
            continue
        max_pos = pos[max_value]
        arr[i], arr[max_pos] = arr[max_pos], arr[i]
        pos[arr[max_pos]] = max_pos
        pos[arr[i]] = i
        k -= 1

    return arr

