def longest_subarray_length(arr, n, k):
    """
    Returns the length of the longest contiguous subarray where the sum is equal to or greater than the threshold k.
    """
    max_length = 0
    for start in range(n):
        current_sum = 0
        for end in range(start, n):
            current_sum += arr[end]
            if current_sum >= k:
                max_length = max(max_length, end - start + 1)
                break
    return max_length

