def max_artifacts(grid, n, m):
    # Create a 2D dp array to store the maximum artifacts collected up to each cell
    dp = [[0] * m for _ in range(n)]

    # Initialize the starting point
    dp[0][0] = grid[0][0]

    # Fill the dp array
    for i in range(n):
        for j in range(m):
            if i > 0:
                dp[i][j] = max(dp[i][j], dp[i-1][j] + grid[i][j])
            if j > 0:
                dp[i][j] = max(dp[i][j], dp[i][j-1] + grid[i][j])

    return dp[n-1][m-1]

