from typing import List

def optimized_bubble_sort(arr: List[int], simulation: bool = False) -> List[int]:
    """
    Sorts a list of integers using an optimized bubble sort algorithm that stops early if no
    elements were swapped during an iteration. If simulation is True, prints the list after
    each iteration.
    """
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
        if simulation:
            print(f"iteration {i+1}: {' '.join(map(str, arr))}")
        if not swapped:
            break
    return arr

