def is_magic_square(square):
    """
    Checks if a given 2D list is a magic square.
    """
    n = len(square)
    if n == 0:
        return False

    expected_sum = sum(square[0])

    # Check rows sum
    for row in square:
        if sum(row) != expected_sum:
            return False

    # Check columns sum
    for col in range(n):
        if sum(square[row][col] for row in range(n)) != expected_sum:
            return False

    # Check diagonals sum
    if sum(square[i][i] for i in range(n)) != expected_sum:
        return False
    if sum(square[i][n-1-i] for i in range(n)) != expected_sum:
        return False

    # Check all numbers from 1 to n^2 are used
    all_nums = sorted([num for row in square for num in row])
    if all_nums != list(range(1, n**2 + 1)):
        return False

    return True

