def generate_magic_square(n):
    """
    Generates a n x n magic square if possible; otherwise returns None.
    """
    if n < 1 or n > 15 or (n % 2 == 0 and n != 4 and (n % 4 != 0)):
        return None

    if n % 2 == 1:  # odd order magic square
        magic_square = [[0]*n for _ in range(n)]
        num = 1
        i, j = 0, n // 2

        while num <= n**2:
            magic_square[i][j] = num
            num += 1
            newi, newj = (i-1) % n, (j+1) % n
            if magic_square[newi][newj]:
                i += 1
            else:
                i, j = newi, newj

        return magic_square

    elif n == 4:  # singly even order magic squares (n mod 4 == 0)
        magic_square = [[(n*y)+x+1 for x in range(n)] for y in range(n)]

        # Swap necessary blocks
        s = n // 4
        for i in range(n):
            for j in range(n):
                if (i < s or i >= n - s) and (j < s or j >= n - s):
                    continue
                elif (i >= s and i < n - s) and (j >= s and j < n - s):
                    continue
                magic_square[i][j] = n*n + 1 - magic_square[i][j]

        return magic_square

    elif n % 4 == 0:  # doubly even order magic squares (n multiple of 4)
        magic_square = [[n*y + x + 1 for x in range(n)] for y in range(n)]

        s = n // 4
        for i in range(n):
            for j in range(n):
                if (i < s or i >= n - s) and (j < s or j >= n - s):
                    magic_square[i][j] = n*n + 1 - magic_square[i][j]
                elif (i >= s and i < n - s) and (j >= s and j < n - s):
                    magic_square[i][j] = n*n + 1 - magic_square[i][j]

        return magic_square

    return None

