def findCommonSubstrings(s1, s2):
    """
    Returns the longest common substrings between s1 and s2.
    """
    len_s1 = len(s1)
    len_s2 = len(s2)

    # Initialize a matrix to store lengths of longest common suffixes of substrings
    lcs_suffix = [[0] * (len_s2 + 1) for i in range(len_s1 + 1)]

    # Store length of longest common substring
    longest_len = 0

    # Set to store all longest common substrings
    common_substrings = set()

    # Build the lcs_suffix matrix
    for i in range(1, len_s1 + 1):
        for j in range(1, len_s2 + 1):
            if s1[i - 1] == s2[j - 1]:
                lcs_suffix[i][j] = lcs_suffix[i - 1][j - 1] + 1
                if lcs_suffix[i][j] > longest_len:
                    longest_len = lcs_suffix[i][j]
                    common_substrings = {s1[i - longest_len:i]}
                elif lcs_suffix[i][j] == longest_len:
                    common_substrings.add(s1[i - longest_len:i])

    return list(common_substrings)

