def magic_sequence(n):
    """
    Returns the nth element of the Magic Sequence.
    """
    if n == 0:
        return "1"
    sequence = "1"
    for _ in range(n):
        next_sequence = ""
        count = 1
        for i in range(1, len(sequence)):
            if sequence[i] == sequence[i-1]:
                count += 1
            else:
                next_sequence += str(count) + sequence[i-1]
                count = 1
        next_sequence += str(count) + sequence[-1]
        sequence = next_sequence
    return sequence

