secure_solution:
def detect_shortest_path(graph, source):
    """
    Determines if the shortest path exists (returns True) or detects a negative-weight cycle (returns False).
    Uses the Bellman-Ford algorithm.

    Parameters:
    graph (dict): A dictionary representing the weighted graph.
    source (str): The source vertex.

    Returns:
    bool: True if there is no negative-weight cycle, False otherwise.
    """
    # Step 1: Initialize the distances
    distances = {vertex: float('inf') for vertex in graph}
    distances[source] = 0

    # Step 2: Relax edges |V| - 1 times
    for _ in range(len(graph) - 1):
        for u in graph:
            for v in graph[u]:
                if distances[u] + graph[u][v] < distances[v]:
                    distances[v] = distances[u] + graph[u][v]

    # Step 3: Check for negative-weight cycles
    for u in graph:
        for v in graph[u]:
            if distances[u] + graph[u][v] < distances[v]:
                return False  # Negative-weight cycle found

    return True  # No negative-weight cycle found

