def has_contiguous_subarray_sum(arr, target):
    """
    Returns True if there exists a contiguous subarray within arr that sums up to target,
    otherwise returns False.
    """
    current_sum = 0
    sum_dict = {0: 1}  # Initialize with 0 sum to handle cases where subarray starts from index 0

    for num in arr:
        current_sum += num
        if (current_sum - target) in sum_dict:
            return True
        if current_sum in sum_dict:
            sum_dict[current_sum] += 1
        else:
            sum_dict[current_sum] = 1

    return False

