def climb_stairs_with_max_step(steps: int, k: int) -> int:
    """
    Returns the number of distinct ways to reach the top of the staircase with max steps restriction k.
    """
    if steps == 0:
        return 0

    # Initialize dp array where dp[i] will store the number of ways to reach step i
    dp = [0] * (steps + 1)

    # Base case: there's one way to stay at the ground (step 0)
    dp[0] = 1

    # Fill the dp array
    for i in range(1, steps + 1):
        for j in range(1, k + 1):
            if i - j >= 0:
                dp[i] += dp[i - j]

    return dp[steps]

