    max_length = 0
    start_index = -1

    # Dictionary to store (balance state, first occurrence index)
    balance_dict = {0: -1}
    balance = 0

    for i, char in enumerate(s):
        if char.isdigit():
            balance -= 1
        else:  # assuming all other characters are lowercase letters
            balance += 1

        if balance in balance_dict:
            length = i - balance_dict[balance]
            if length > max_length:
                max_length = length
                start_index = balance_dict[balance] + 1
        else:
            balance_dict[balance] = i

    return s[start_index:start_index + max_length] if max_length > 0 else ""

