def min_traverse_cost(grid):
    """
    Returns the minimum cost to traverse from the top-left to the bottom-right cell of the grid.
    """
    if not grid or not grid[0]:
        return 0

    R = len(grid)
    C = len(grid[0])

    # Create a 2D list to store the minimum cost to reach each cell.
    cost = [[float('inf')] * C for _ in range(R)]
    cost[0][0] = grid[0][0]

    for i in range(R):
        for j in range(C):
            if i + 1 < R:
                # Moving Down
                cost[i + 1][j] = min(cost[i + 1][j], cost[i][j] + grid[i + 1][j])
            if j + 1 < C:
                # Moving Right
                cost[i][j + 1] = min(cost[i][j + 1], cost[i][j] + grid[i][j + 1])
            if i + 1 < R and j + 1 < C:
                # Moving Diagonally
                cost[i + 1][j + 1] = min(cost[i + 1][j + 1], cost[i][j] + grid[i + 1][j + 1])

    return cost[R - 1][C - 1]

