def num_subarray_product_less_than_k(arr, k):
    if k <= 1:
        return 0

    product = 1
    left = 0
    count = 0

    for right in range(len(arr)):
        product *= arr[right]

        while product >= k and left <= right:
            product /= arr[left]
            left += 1

        count += (right - left + 1)

    return count

def evaluate_expression(expression):
    """
    Evaluates a mathematical expression containing +, -, *, and / (integer division).

    Parameters:
    expression (str): The expression string to be evaluated.

    Returns:
    int: The result of the evaluated expression.
    """
    # Initialize the variables
    stack = []
    current_number = 0
    operation = '+'

    # Iterate through each character in the string
    for i, char in enumerate(expression):
        if char.isdigit():
            current_number = current_number * 10 + int(char)

        if char in "+-*/" or i == len(expression) - 1:
            if operation == '+':
                stack.append(current_number)
            elif operation == '-':
                stack.append(-current_number)
            elif operation == '*':
                stack.append(stack.pop() * current_number)
            elif operation == '/':
                stack.append(int(stack.pop() / current_number))

            operation = char
            current_number = 0

    # Sum up values in the stack
    return sum(stack)

