def minimal_weight_difference(n, weights):
    total_sum = sum(weights)
    half_sum = total_sum // 2

    dp = [False] * (half_sum + 1)
    dp[0] = True

    for weight in weights:
        for i in range(half_sum, weight - 1, -1):
            dp[i] = dp[i] or dp[i - weight]

    for i in range(half_sum, -1, -1):
        if dp[i]:
            return abs(total_sum - 2 * i)

    return total_sum

