from typing import List, Tuple

def enhanced_insertion_sort(arr: List[int]) -> Tuple[List[int], int]:
    n = len(arr)
    if n == 0:
        return (arr, 0)

    swaps = 0
    for i in range(1, n):
        key = arr[i]
        j = i - 1
        while j >= 0 and arr[j] > key:
            arr[j + 1] = arr[j]
            j -= 1
            swaps += 1
        arr[j + 1] = key

    return (arr, swaps)

