def findMaxLength(s):
    """
    Finds the length of the longest contiguous substring with equal number of 0s and 1s.
    """
    count = 0
    max_length = 0
    count_map = {0: -1} 

    for i, char in enumerate(s):
        count += 1 if char == '1' else -1

        if count in count_map:
            max_length = max(max_length, i - count_map[count])
        else:
            count_map[count] = i

    return max_length

