def ensure_difference(arr, d):
    """
    Ensures that for every element in the array, the absolute difference
    between any two consecutive elements is less than or equal to d.
    """
    n = len(arr)

    if not arr or n < 2:
        return arr

    result = [arr[0]]

    for i in range(1, n):
        if abs(arr[i] - result[-1]) > d:
            result.append(result[-1] + d if arr[i] > result[-1] else result[-1] - d)
        else:
            result.append(arr[i])

    return result

