def roman_to_integer(roman: str) -> int:
    roman_to_int_map = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    # Rules for valid Roman Numeral
    valid_subtractive_combinations = ['IV', 'IX', 'XL', 'XC', 'CD', 'CM']

    # Validation for an empty string
    if not roman:
        return -1

    # Step 1: Validate input string is a valid Roman numeral
    for char in roman:
        if char not in roman_to_int_map:
            return -1

    # Check valid repetition of characters
    if 'IIII' in roman or 'VV' in roman or 'XXXX' in roman or 'LL' in roman or 'CCCC' in roman or 'DD' in roman or 'MMMM' in roman:
        return -1

    # Check valid subtractive combinations and non-valid combinations
    index = 0
    while index < len(roman):
        if index + 1 < len(roman) and (roman[index] + roman[index + 1]) not in valid_subtractive_combinations:
            if roman[index + 1] in roman_to_int_map and roman_to_int_map[roman[index]] < roman_to_int_map[roman[index + 1]]:
                return -1
        index += 1

    # Step 2: Conversion
    result = 0
    i = 0
    while i < len(roman):
        # If this is a subtractive combination
        if i + 1 < len(roman) and (roman[i] + roman[i + 1]) in valid_subtractive_combinations:
            result += roman_to_int_map[roman[i + 1]] - roman_to_int_map[roman[i]]
            i += 2
        # Otherwise, just add the value
        else:
            result += roman_to_int_map[roman[i]]
            i += 1

    return result

