def evaluate_rpn(expression):
    """
    Evaluates a Reverse Polish Notation (RPN) expression.

    :param expression: A string containing a valid RPN expression.
    :return: An integer that is the evaluation result of the RPN expression.
    """
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        else:
            # Operator encountered, pop top two elements from stack
            b = stack.pop()
            a = stack.pop()

            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a // b)

    return stack[0]

