def unique_paths_with_barriers(grid):
    """
    Function to find the number of unique paths from top-left to bottom-right
    in an n x n grid with barriers where movement is only allowed down or right.
    """
    n = len(grid)
    if grid[0][0] == '#' or grid[n-1][n-1] == '#':
        return 0

    # Initialize a 2D DP array with zeros
    dp = [[0] * n for _ in range(n)]

    # Start point
    dp[0][0] = 1

    for i in range(n):
        for j in range(n):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][n-1]

