def kth_smallest_pair_sum(n, k, nums):
    """
    Finds the k-th smallest sum of distinct pairs in a list of numbers.
    """
    sums = []
    for i in range(n):
        for j in range(i + 1, n):
            sums.append(nums[i] + nums[j])
    sums.sort()
    return sums[k - 1]

