def max_sum_of_magic_values(N, L, magic_values):
    MOD = 1000000009

    # Initialize dp array where dp[i][j] is the maximum sum using j subarrays in the first i books
    dp = [[-float('inf')] * (L + 1) for _ in range(N + 1)]

    # Base case: zero books, zero subarrays
    dp[0][0] = 0

    for i in range(1, N + 1):
        max_val = 0
        for j in range(1, L + 1):
            for k in range(i):
                max_val = max(max_val, dp[k][j-1] + max(magic_values[k:i]))
            dp[i][j] = max_val

    return dp[N][L] % MOD

