def longest_contiguous_sublist(n, lst):
    """
    Returns the length of the longest contiguous sublist consisting of either all even or all odd integers.
    """
    if n == 0:
        return 0

    max_length = 1
    current_length = 1
    for i in range(1, n):
        if (lst[i] % 2 == lst[i - 1] % 2):
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1

    return max(max_length, current_length)

