def longest_increasing_subsequence(n, sequence):
    """
    Returns the length of the longest strictly increasing subsequence.

    Parameters:
    n (int): The number of elements in the sequence.
    sequence (list of int): The sequence of numbers.

    Returns:
    int: The length of the longest strictly increasing subsequence.
    """
    if n == 0:
        return 0

    # Initialize an array to keep the longest increasing subsequence lengths
    LIS = [1] * n

    for i in range(1, n):
        for j in range(0, i):
            if sequence[i] > sequence[j]:
                LIS[i] = max(LIS[i], LIS[j] + 1)

    return max(LIS)

