secure_solution:
def max_crops_in_subgrid(grid: list[list[int]], k: int) -> int:
    m, n = len(grid), len(grid[0])
    max_sum = float('-inf')

    # Create an auxiliary sum array to store sums of sub-grids
    sum_grid = [[0] * (n + 1) for _ in range(m + 1)]

    # Building the prefix sum grid
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            sum_grid[i][j] = grid[i - 1][j - 1] + sum_grid[i - 1][j] + sum_grid[i][j - 1] - sum_grid[i - 1][j - 1]

    # Calculate the sum of each kxk sub-grid
    for i in range(k, m + 1):
        for j in range(k, n + 1):
            current_sum = sum_grid[i][j] - sum_grid[i - k][j] - sum_grid[i][j - k] + sum_grid[i - k][j - k]
            max_sum = max(max_sum, current_sum)

    return max_sum

