def can_rearrange_robots(test_cases):
    results = []

    for n, board in test_cases:
        # Validate that each row contains exactly one 'R'
        valid_row = all(row.count('R') == 1 for row in board)

        if not valid_row:
            results.append("NO")
            continue

        # Collect columns for each robot
        columns_with_robots = [row.index('R') for row in board]

        # Validate that all column indices are unique
        if len(set(columns_with_robots)) == n:
            results.append("YES")
        else:
            results.append("NO")

    return results

