def min_boxes_required(N, W, weights):
    weights.sort(reverse=True)
    boxes = []

    for weight in weights:
        placed = False
        for box in boxes:
            if sum(box) + weight <= W:
                box.append(weight)
                placed = True
                break
        if not placed:
            boxes.append([weight])

    return len(boxes)

