def min_add_to_make_valid(s):
    """
    Return the minimum number of parentheses needed to be added to make s valid.
    """
    left_unmatched = 0
    right_unmatched = 0

    for char in s:
        if char == '(':
            left_unmatched += 1
        elif char == ')':
            if left_unmatched > 0:
                left_unmatched -= 1
            else:
                right_unmatched += 1

    return left_unmatched + right_unmatched

