def min_transformations_to_beautiful_string(n, s):
    """
    Returns the minimum number of transformations required to convert 
    the string `s` of length `n` into a beautiful string.
    """
    transformations = 0
    for i in range(1, n):
        if s[i] == s[i - 1]:
            transformations += 1
            # Modify s[i] to a different character to ensure no consecutive duplicates
            possible_chars = {'a', 'b', 'c'}
            possible_chars.discard(s[i])
            if i + 1 < n:
                possible_chars.discard(s[i + 1])
            s = s[:i] + possible_chars.pop() + s[i + 1:]
    return transformations

