def min_bonus(ratings):
    """
    Returns the minimum number of bonus units the company needs to distribute.

    Parameters:
    ratings (List[int]): List of rating scores for each employee.

    Returns:
    int: Minimum number of bonus units to be distributed.
    """
    n = len(ratings)
    if n == 0:
        return 0

    bonuses = [1] * n

    # Left to right pass to ensure right neighbor condition
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            bonuses[i] = bonuses[i - 1] + 1

    # Right to left pass to ensure left neighbor condition
    for j in range(n - 2, -1, -1):
        if ratings[j] > ratings[j + 1]:
            bonuses[j] = max(bonuses[j], bonuses[j + 1] + 1)

    return sum(bonuses)

