def find_pair_with_sum_divisible_by_k(n, k, array):
    """
    Returns two indices i and j such that the sum of the elements at these indices is divisible by k.
    """
    # Dictionary to store the remainders and their corresponding indices
    remainder_dict = {}

    for index, value in enumerate(array):
        remainder = value % k
        complement = (k - remainder) % k  # Complement remainder to make the sum divisible by k

        if complement in remainder_dict:
            return remainder_dict[complement] + 1, index + 1

        remainder_dict[remainder] = index

    return -1, -1  # In case no valid pair is found; though problem states that a pair always exists

