def all_anagrams(word_list):
    """
    Returns a dictionary where each key is a sorted string of characters
    and the corresponding value is a list of words from the input that 
    are anagrams of each other.
    """
    anagrams = {}
    for word in word_list:
        sorted_word = ''.join(sorted(word))
        if sorted_word not in anagrams:
            anagrams[sorted_word] = []
        anagrams[sorted_word].append(word)
    return anagrams

from collections import Counter
from typing import List

def canPartition(cards: List[int], groupSize: int) -> bool:
    """
    Returns True if it's possible to partition the deck into groups of exactly groupSize
    consecutive cards. Otherwise returns False.
    """
    if len(cards) % groupSize != 0:
        return False

    card_count = Counter(cards)

    while card_count:
        min_card = min(card_count)

        for i in range(groupSize):
            current_card = min_card + i

            if card_count[current_card] == 0:
                return False

            card_count[current_card] -= 1
            if card_count[current_card] == 0:
                del card_count[current_card]

    return True

