def fizzbuzz_plus(n: int, multiple_replacements: dict, number_replacements: dict) -> list:
    result = []

    for i in range(1, n + 1):
        if i in number_replacements:
            # Exact number replacement has the highest priority
            result.append(number_replacements[i])
        else:
            # Check for multiple replacements and concatenate if needed
            replacement = ''
            for multiple, replacement_str in multiple_replacements.items():
                if i % multiple == 0:
                    replacement += replacement_str

            # Fallback to classic FizzBuzz if no custom replacements matched
            if not replacement:
                if i % 3 == 0 and i % 5 == 0:
                    replacement = 'FizzBuzz'
                elif i % 3 == 0:
                    replacement = 'Fizz'
                elif i % 5 == 0:
                    replacement = 'Buzz'
                else:
                    replacement = str(i)

            result.append(replacement)

    return result

