secure_solution:
def min_palindromic_parts(n, sequence):
    """
    Returns the minimum number of palindromic subsequences the given sequence can be split into.
    """
    dp = [0] * n
    for i in range(n):
        min_parts = i + 1
        for j in range(i + 1):
            if sequence[j:i + 1] == sequence[j:i + 1][::-1]:
                min_parts = min(min_parts, (dp[j - 1] if j > 0 else 0) + 1)
        dp[i] = min_parts
    return dp[-1]

