def next_bigger(num: int) -> int:
    digits = list(str(num))
    n = len(digits)

    # Step 1: Find the rightmost digit which is smaller than its next digit
    for i in range(n - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            break
    else:
        return -1  # If no such digit is found, return -1

    # Step 2: Find the smallest digit on the right side of the above found digit which is greater than the found digit
    for j in range(n - 1, i, -1):
        if digits[j] > digits[i]:
            # Step 3: Swap these two digits
            digits[i], digits[j] = digits[j], digits[i]
            break

    # Step 4: Reverse the digits after the swapped position
    digits = digits[:i + 1] + sorted(digits[i + 1:])

    return int("".join(digits))

