from collections import deque

def time_to_propagate_signal(grid):
    if not grid:
        return -1

    rows, cols = len(grid), len(grid[0])
    queue = deque()
    visited = set()
    empty_cells = 0

    # Initialize the queue with all starting points and count empty cells
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                queue.append((r, c, 0))  # (row, column, time)
                visited.add((r, c))
            elif grid[r][c] == 0:
                empty_cells += 1

    # Edge case: if no empty cells exist
    if empty_cells == 0:
        return 0

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    max_time = 0

    while queue:
        r, c, time = queue.popleft()

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                if grid[nr][nc] == 0:
                    visited.add((nr, nc))
                    queue.append((nr, nc, time + 1))
                    max_time = time + 1
                    empty_cells -= 1

    # If there are still empty cells that cannot be reached
    if empty_cells > 0:
        return -1

    return max_time

