def find_pairs(n):
    """
    Returns a list of tuples representing pairs (a, b) such that:
    - a and b are positive integers
    - a < b
    - a * b = n
    - The list is sorted by increasing order of `a`.
    """
    if n <= 1:
        return []

    pairs = []
    for a in range(1, int(n**0.5) + 1):
        if n % a == 0:
            b = n // a
            if a < b:
                pairs.append((a, b))
            elif a == b:
                pairs.append((a, a))
    return pairs

