def convert_digits(s):
    """
    Converts every digit in the string into '0' if it is even or '1' if it is odd.
    Non-digit characters remain unchanged.

    :param s: A string containing lowercase letters and integers
    :return: Modified string with converted digits
    """
    result = []
    for char in s:
        if char.isdigit():
            if int(char) % 2 == 0:
                result.append('0')
            else:
                result.append('1')
        else:
            result.append(char)
    return ''.join(result)

