def find_repeated_substrings(s, k):
    """
    Returns a list of unique substrings of length `k` that appear more than once in the string `s`.

    Args:
    s (str): The input string containing only lowercase letters.
    k (int): The length of the substrings to find.

    Returns:
    list: A list of unique substrings of length `k` that appear more than once in the string.
    """
    if k <= 0 or len(s) < k:
        return []

    substring_count = {}
    for i in range(len(s) - k + 1):
        substring = s[i:i+k]
        if substring in substring_count:
            substring_count[substring] += 1
        else:
            substring_count[substring] = 1

    return [substring for substring, count in substring_count.items() if count > 1]

