def max_difficulty_sum(n, D, difficulties):
    """
    Returns the maximum possible sum of the difficulty ratings that does not exceed D.
    """
    # Use dynamic programming to solve this knapsack-like problem.
    dp = [0] * (D + 1)

    for difficulty in difficulties:
        for i in range(D, difficulty-1, -1):
            dp[i] = max(dp[i], dp[i-difficulty] + difficulty)

    return dp[D]

def two_sum(nums, target):
    """
    Returns indices of the two numbers such that they add up to the given target.

    Args:
        nums: List of integers.
        target: The target sum integer.

    Returns:
        A tuple of two integers representing indices of the two numbers.
    """
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return (seen[complement], i)
        seen[num] = i

