def aggregate_movie_ratings(reviews):
    from collections import defaultdict

    totals = defaultdict(int)
    counts = defaultdict(int)

    for review in reviews:
        try:
            title, critic, rating = review
            if not isinstance(title, str) or not isinstance(critic, str) or not isinstance(rating, int):
                continue
            if rating < 1 or rating > 10:
                continue
            totals[title] += rating
            counts[title] += 1
        except ValueError:
            continue

    averages = {}
    for title in totals:
        averages[title] = round(totals[title] / counts[title], 1)

    return averages

