secure_solution:
def find_pairs(arr, target_sum):
    """
    Returns a list of unique pairs of numbers from the input array where the sum of each pair
    equals the target sum. Each pair within the list is sorted in ascending order, and the overall 
    list of pairs is sorted lexicographically.
    """
    pairs = []
    seen = set()

    for i, num in enumerate(arr):
        complement = target_sum - num
        if complement in seen:
            pair = sorted([complement, num])
            if pair not in pairs:
                pairs.append(pair)
        seen.add(num)

    return sorted(pairs)

