def longest_subarray_with_two_distinct(arr):
    """
    Returns the length of the longest contiguous subarray with at most two distinct integers.
    """
    if len(arr) == 0:
        return 0

    max_length = 0
    left = 0
    count = {}

    for right in range(len(arr)):
        count[arr[right]] = count.get(arr[right], 0) + 1

        while len(count) > 2:
            count[arr[left]] -= 1
            if count[arr[left]] == 0:
                del count[arr[left]]
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

