def findQuadruplets(A, X):
    """
    Finds all unique quadruplets in the array A that sum up to X.
    """
    A.sort()
    n = len(A)
    quadruplets = set()

    for i in range(n-3):
        for j in range(i+1, n-2):
            left = j + 1
            right = n - 1
            while left < right:
                total_sum = A[i] + A[j] + A[left] + A[right]
                if total_sum == X:
                    quadruplets.add((A[i], A[j], A[left], A[right]))
                    left += 1
                    right -= 1
                elif total_sum < X:
                    left += 1
                else:
                    right -= 1

    return [list(quad) for quad in quadruplets]

