def max_consecutive_increasing_temps(temps):
    """
    Returns the maximum number of consecutive days with a strictly increasing temperature trend.
    """
    if not temps:
        return 0

    max_length = 0
    current_length = 1  # at least one day itself is an increasing sequence

    for i in range(1, len(temps)):
        if temps[i] > temps[i-1]:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1  # reset the current length

    max_length = max(max_length, current_length)  # final check for the last sequence
    return max_length

