def climbStairs(n, m):
    """
    Returns the count of distinct ways to climb a staircase of n steps
    using step sizes from the set {1, 2, ..., m}.
    """
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if i >= j:
                dp[i] += dp[i - j]

    return dp[n]

