def find_substrings(S, K):
    """
    Returns the lexicographically smallest and largest substrings of length K from string S.
    """
    # Initialize smallest and largest substrings
    smallest = largest = S[:K]

    # Iterate through each possible substring of length K
    for i in range(1, len(S) - K + 1):
        substring = S[i:i+K]
        if substring < smallest:
            smallest = substring
        if substring > largest:
            largest = substring

    return (smallest, largest)

