def maxReward(budget, cities):
    # Implement a dynamic programming solution
    dp = [0] * (budget + 1)  # dp[i] = maximum reward we can get with a budget of i

    for cost, reward in cities:
        # We iterate backwards to make sure each city is chosen only once
        for b in range(budget, cost - 1, -1):
            dp[b] = max(dp[b], dp[b - cost] + reward)

    return max(dp)  # The maximum reward we can get with budgets from 0 to the given budget

