def restore_smallest_number(s):
    """
    Replaces '?' with digits (0-9) to form the smallest possible number.
    Ensures no leading zeros unless the number is '0'.
    """
    if len(s) == 0:
        return "IMPOSSIBLE"

    # Replace '?' characters
    s_list = list(s)
    if s_list[0] == '?':
        s_list[0] = '1' if len(s) > 1 else '0'
    for i in range(1, len(s_list)):
        if s_list[i] == '?':
            s_list[i] = '0'

    # Ensure valid number
    if len(s_list) > 1 and s_list[0] == '0':
        return "IMPOSSIBLE"

    return ''.join(s_list)

