def check_subarray_sum(nums, k):
    """
    Checks if there is a contiguous subarray that sums to a multiple of k.

    Parameters:
    nums (list of int): List of non-negative integers.
    k (int): Target multiple integer.

    Returns:
    bool: True if such a subarray exists, otherwise False.
    """
    if k == 0:
        return any(sum(nums[i:i+2]) == 0 for i in range(len(nums) - 1))

    mod_map = {0: -1}  # remainder -> first index where this remainder was seen
    total = 0

