def remove_outer_parentheses(S):
    """
    Removes the outermost parentheses of every primitive string.

    :param S: A string containing only lowercase alphabets and parentheses
    :return: A string with the outermost parentheses removed from every primitive string
    """
    result = []
    opened = 0
    for char in S:
        if char == '(':
            if opened > 0:
                result.append(char)
            opened += 1
        elif char == ')':
            if opened > 1:
                result.append(char)
            opened -= 1
    return ''.join(result)

