def min_path_sum(matrix):
    """
    Given a matrix of integers where each element represents the cost of moving through that cell,
    returns the minimum cost to reach the bottom-right cell from the top-left cell.
    You can only move either right or down at any point in time.
    """
    if not matrix or not matrix[0]:
        return 0

    rows, cols = len(matrix), len(matrix[0])
    dp = [[0] * cols for _ in range(rows)]

    dp[0][0] = matrix[0][0]

    for i in range(1, rows):
        dp[i][0] = dp[i - 1][0] + matrix[i][0]

    for j in range(1, cols):
        dp[0][j] = dp[0][j - 1] + matrix[0][j]

    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + matrix[i][j]

    return dp[-1][-1]

def can_park_all_cars(m, capacities, n, car_times):
    parking_state = [[0] * c for c in capacities]  # create parking state per level
    car_positions = []

    for t_arr, t_dep in car_times:
        parked = False
        for level in range(m):
            for spot in range(capacities[level]):
                if parking_state[level][spot] <= t_arr:
                    parking_state[level][spot] = t_dep
                    car_positions.append(level + 1)
                    parked = True
                    break
            if parked:
                break
        if not parked:
            return False, []

    return True, car_positions

