def perform_operations(n, q, array, operations):
    """
    Perform operations as specified on the given array.
    :param n: Number of elements in the array (int)
    :param q: Number of operations (int)
    :param array: List of integers representing the initial array
    :param operations: List of operations, each operation being a list [t, l, r, k]
    :return: List of results for each query of the third type (sum operations)
    """
    results = []
    for operation in operations:
        t, l, r, k = operation
        if t == 1:
            for i in range(l-1, r):
                array[i] += k
        elif t == 2:
            for i in range(l-1, r):
                array[i] -= k
        elif t == 3:
            subarray_sum = sum(array[l-1:r])
            results.append(subarray_sum)
    return results

