def min_operations_to_make_strings_equal(n, a, b):
    operations = 0
    i = 0

    while i < n:
        # If the current character positions are different
        if a[i] != b[i]:
            # Check if swappable bit flip is possible
            # Only consider swap when there's enough length to check next bit and next bits are opposite 
            if i + 1 < n and a[i] != a[i + 1] and b[i] != b[i + 1] and a[i] == b[i + 1] and a[i + 1] == b[i]:
                # Count swap as one operation
                operations += 1
                i += 2  # Skip next bit as it is already considered in swap
            else:
                # If no swap is possible, just flip the current bit
                operations += 1
                i += 1  # Move to next bit
        else:
            # If already same, move to next bit
            i += 1

    return operations

