import math

def calculate_parabolic_motion(initial_speed: float, angle: float) -> dict[str, float]:
    if initial_speed <= 0:
        raise ValueError("Initial speed must be greater than 0")
    if not (0 <= angle <= 90):
        raise ValueError("Angle must be between 0 and 90 degrees")

    g = 9.81  # Acceleration due to gravity in m/s^2
    angle_rad = math.radians(angle)

    maximum_height = (initial_speed**2 * math.sin(angle_rad)**2) / (2 * g)
    horizontal_range = (initial_speed**2 * math.sin(2 * angle_rad)) / g

    return {
        'maximum_height': maximum_height,
        'horizontal_range': horizontal_range
    }

