def remove_duplicate_letters(s):
    """
    Given a string s, remove the duplicate letters such that every letter appears once and only once,
    and return the smallest in lexicographical order that can result from removing the duplicate letters.
    """
    stack = []
    seen = set()
    last_occurrence = {char: i for i, char in enumerate(s)}

    for i, char in enumerate(s):
        if char not in seen:
            while stack and char < stack[-1] and i < last_occurrence[stack[-1]]:
                seen.discard(stack.pop())
            seen.add(char)
            stack.append(char)

    return ''.join(stack)

