def unique_paths_with_obstacles(test_cases):
    MOD = 10**9 + 7
    results = []

    for M, N, grid in test_cases:
        # Create DP table
        dp = [[0] * N for _ in range(M)]

        # If the starting cell has an obstacle, return 0 paths
        if grid[0][0] == '#' or grid[M-1][N-1] == '#':
            results.append(0)
            continue

        # Initial value to start the path
        dp[0][0] = 1

        # Fill the DP table
        for r in range(M):
            for c in range(N):
                if grid[r][c] == '#':
                    dp[r][c] = 0
                else:
                    if r > 0:
                        dp[r][c] += dp[r-1][c]
                    if c > 0:
                        dp[r][c] += dp[r][c-1]
                    dp[r][c] %= MOD

        results.append(dp[M-1][N-1])

    return results

