from typing import List

def is_valid_wave(wave: List[str]) -> bool:
    """
    Determine if the provided wave is valid. A wave is valid if no two words contain the same character.
    """
    all_characters = set()

    for word in wave:
        for char in word:
            if char in all_characters:
                return False
            all_characters.add(char)

    return True

