def maxProfit(k, prices):
    """
    Returns the maximum profit achievable with at most k transactions.

    :param k: int - maximum number of transactions allowed
    :param prices: List[int] - list of stock prices on consecutive days
    :return: int - maximum profit achievable
    """
    if not prices or k == 0:
        return 0

    n = len(prices)

    if k >= n // 2:
        return sum(
            max(prices[i + 1] - prices[i], 0) for i in range(n - 1)
        )

    profits = [[0] * (n) for _ in range(k + 1)]

    for t in range(1, k + 1):
        max_to_buy = -prices[0]
        for d in range(1, n):
            profits[t][d] = max(profits[t][d - 1], prices[d] + max_to_buy)
            max_to_buy = max(max_to_buy, profits[t - 1][d] - prices[d])

    return profits[k][n - 1]

