def subset_sum(n, arr, T):
    """
    Determines if there's a subset of `arr` that sums up to `T`.
    Returns 'YES' or 'NO'.
    """
    # Initialize a table to store the results of sub problems
    dp = [[False] * (T + 1) for _ in range(n + 1)]

    # There is a subset with the sum 0, which is the empty subset
    for i in range(n + 1):
        dp[i][0] = True

    # Fill in the subset sum table
    for i in range(1, n + 1):
        for j in range(1, T + 1):
            if arr[i-1] > j:
                dp[i][j] = dp[i-1][j]
            else:
                dp[i][j] = dp[i-1][j] or dp[i-1][j - arr[i-1]]

    return 'YES' if dp[n][T] else 'NO'

