def find_length_of_longest_common_subarray(seq1, seq2):
    n = len(seq1)
    m = len(seq2)

    # Create a 2D array to store the lengths of longest common suffixes
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    max_length = 0  # Initialize the maximum length

    # Populate the dp array
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            # If elements match, extend the common subarray length
            if seq1[i - 1] == seq2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                max_length = max(max_length, dp[i][j])
            else:
                dp[i][j] = 0  # Reset if there's no match

    return max_length

