from typing import List

def canCross(nums: List[int]) -> bool:
    if not nums or nums[0] != 0:
        return False

    n = len(nums)
    if n == 1:
        return True

    # A dictionary where key is the stone and value is a set of jump sizes that can reach this stone
    jumps = {stone: set() for stone in nums}
    jumps[0].add(1)

    for stone in nums:
        for jump in jumps[stone]:
            reach = stone + jump
            if reach == nums[-1]:
                return True
            if reach in jumps:
                if jump - 1 > 0:
                    jumps[reach].add(jump - 1)
                jumps[reach].add(jump)
                jumps[reach].add(jump + 1)

    return False

