def can_split_into_equal_sum_subsequences(n, nums):
    total_sum = sum(nums)

    # If the total sum is odd, it's not possible to split into two equal parts
    if total_sum % 2 != 0:
        return "NO"

    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True

    for num in nums:
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    return "YES" if dp[target] else "NO"

