def min_operations_to_transform(initial, target):
    n = len(initial)
    m = len(target)

    # dp[i][j] will be the minimum number of operations required to transform
    # initial[0...i-1] into target[0...j-1]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: transforming string to an empty string
    for i in range(1, n + 1):
        dp[i][0] = i

    for j in range(1, m + 1):
        dp[0][j] = j

    # Fill dp array
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if initial[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j - 1], dp[i][j - 1], dp[i - 1][j]) + 1

    # Now to find the operations
    i, j = n, m
    operations = []

    while i > 0 and j > 0:
        if initial[i - 1] == target[j - 1]:
            i -= 1
            j -= 1
        else:
            if dp[i][j] == dp[i - 1][j - 1] + 1:
                operations.append(f"Replace {i} {target[j - 1]}")
                i -= 1
                j -= 1
            elif dp[i][j] == dp[i][j - 1] + 1:
                operations.append(f"Insert {i + 1} {target[j - 1]}")
                j -= 1
            else:
                operations.append(f"Delete {i}")
                i -= 1

    while i > 0:
        operations.append(f"Delete {i}")
        i -= 1

    while j > 0:
        operations.append(f"Insert {1} {target[j - 1]}")
        j -= 1

    operations.reverse()
    return dp[n][m], operations

