    smallest_arr = arr[:]

    for i in range(n):
        for j in range(i, min(i + k, n)):
            subarray = arr[i:j+1][::-1]
            new_arr = arr[:i] + subarray + arr[j+1:]
            if new_arr < smallest_arr:
                smallest_arr = new_arr

    return smallest_arr

