def longest_substring_two_distinct(s: str) -> int:
    """
    This function finds the length of the longest substring with at most two distinct characters.
    """
    if not s:
        return 0

    left = 0
    max_length = 0
    char_map = {}

    for right in range(len(s)):
        char = s[right]
        if char in char_map:
            char_map[char] += 1
        else:
            char_map[char] = 1

        while len(char_map) > 2:
            left_char = s[left]
            char_map[left_char] -= 1
            if char_map[left_char] == 0:
                del char_map[left_char]
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

