from typing import List, Tuple, Dict

def schedule_jobs(jobs: List[Tuple[int, int]], workers: List[str]) -> Dict[str, Tuple[int, int]]:
    # Sort jobs based on priority in descending order
    sorted_jobs = sorted(jobs, key=lambda job: (-job[1], jobs.index(job)))

    # Assign jobs to workers
    assignments = {}
    for i in range(min(len(workers), len(jobs))):
        assignments[workers[i]] = sorted_jobs[i]

    return assignments

def num_decodings(s: str) -> int:
    if not s or s[0] == '0':
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    # Base cases
    dp[0] = 1
    dp[1] = 1 if s[0] != '0' else 0

    for i in range(2, n + 1):
        one_digit = int(s[i - 1:i])
        two_digits = int(s[i - 2:i])

        if 1 <= one_digit <= 9:
            dp[i] += dp[i - 1]
        if 10 <= two_digits <= 26:
            dp[i] += dp[i - 2]

    return dp[n]

