def max_area_in_strip(heights, k):
    """
    Returns the maximum area of rectangular strip of width k in consecutive buildings.
    """
    n = len(heights)
    if k > n:
        return 0

    max_area = 0

    for i in range(n - k + 1):
        min_height = heights[i]
        for j in range(1, k):
            if heights[i + j] < min_height:
                min_height = heights[i + j]
        current_area = min_height * k
        if current_area > max_area:
            max_area = current_area

    return max_area

