secure_solution:
def is_balanced_bracket_string(s):
    """
    Determines if the input string s is a Balanced Bracket String.
    """
    bracket_stack = []
    bracket_pairs = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_pairs.values():
            bracket_stack.append(char)
        elif char in bracket_pairs:
            if not bracket_stack or bracket_stack[-1] != bracket_pairs[char]:
                return False
            bracket_stack.pop()
        else:
            return False

    return not bracket_stack

