def min_steps_to_palindrome(s):
    """
    Returns the minimum number of steps required to make the string a palindrome.
    """
    if not s:
        return 0

    n = len(s)
    steps = 0

    # Compare characters from start and end towards the center
    for i in range(n // 2):
        if s[i] != s[n - i - 1]:
            steps += 1

    return steps

