def min_operations_to_balance(s: str) -> int:
    """
    Returns the minimum number of operations required to balance the parentheses string.
    """
    # Count of left '(' and right ')' parentheses needed
    left_needed = 0
    right_needed = 0

    for char in s:
        if char == '(':
            right_needed += 1  # We need a corresponding ')'
        elif char == ')':
            if right_needed > 0:
                right_needed -= 1  # We have a matching '('
            else:
                left_needed += 1  # We need a corresponding '('

    # The total operations needed is the sum of left_needed and right_needed
    return left_needed + right_needed

