def longest_common_prefix(strings):
    """
    Returns the longest common prefix among a list of strings.
    """
    if not strings:
        return ""

    # Start by assuming the entire first string is the common prefix
    prefix = strings[0]

    # Iterate over all strings in the list
    for string in strings[1:]:
        # Shorten the prefix as long as it's not a prefix of the current string
        while string[:len(prefix)] != prefix and prefix:
            prefix = prefix[:-1]
        if not prefix:
            break

    return prefix

