from collections import Counter, defaultdict

def min_window(s, p):
    if not s or not p:
        return ""

    dict_p = Counter(p)
    required = len(dict_p)
    left, right = 0, 0
    formed = 0
    window_counts = defaultdict(int)
    ans = float("inf"), None, None

    while right < len(s):
        character = s[right]
        window_counts[character] += 1

        if character in dict_p and window_counts[character] == dict_p[character]:
            formed += 1

        while left <= right and formed == required:
            character = s[left]
            end = right - left + 1
            if end < ans[0]:
                ans = (end, left, right)

            window_counts[character] -= 1
            if character in dict_p and window_counts[character] < dict_p[character]:
                formed -= 1

            left += 1

        right += 1

    if ans[0] == float("inf"):
        return ""
    else:
        return s[ans[1]: ans[2] + 1]

