def find_duplicates(nums):
    """
    Returns a list of duplicate numbers in the input list `nums`.
    Each element in the output list must be unique.
    """
    duplicates = []
    for num in nums:
        index = abs(num) - 1
        if nums[index] < 0:
            duplicates.append(abs(num))
        else:
            nums[index] = -nums[index]
    # Restore nums to its original values
    for i in range(len(nums)):
        nums[i] = abs(nums[i])
    return duplicates

def fibonacci(n: int) -> int:
    """
    Returns the nth Fibonacci number.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

