def num_decodings(s):
    """
    Returns the number of ways to decode the string 's'.
    """
    if not s:
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]
        if i != 1 and '10' <= s[i-2:i] <= '26':
            dp[i] += dp[i - 2]

    return dp[n]

