def largest_rectangular_block(matrix):
    if not matrix:
        return 0

    n = len(matrix)
    m = len(matrix[0])
    max_area = 0

    for c in range(26):
        char = chr(ord('a') + c)

        height = [0] * (m + 1)
        for i in range(n):
            for j in range(m):
                if matrix[i][j] == char:
                    height[j] += 1
                else:
                    height[j] = 0

            stack = [-1]
            for k in range(m + 1):
                while height[k] < height[stack[-1]]:
                    h = height[stack.pop()]
                    w = k - stack[-1] - 1
                    max_area = max(max_area, h * w)
                stack.append(k)

    return max_area

