def can_cross(stones):
    """
    Determine if you can cross the river by landing on the last stone.

    :param stones: List[int] - A list of stone positions in increasing order.
    :return: bool - True if you can reach the last stone, False otherwise.
    """
    if not stones:
        return False

    # Dictionary to hold the reachable distances from each stone
    stone_reach = {stone: set() for stone in stones}
    stone_reach[stones[0]].add(0)

    for stone in stones:
        for jump in stone_reach[stone]:
            # Check for jump - 1, jump, and jump + 1
            for k in range(jump - 1, jump + 2):
                if k > 0 and stone + k in stone_reach:
                    stone_reach[stone + k].add(k)

    return bool(stone_reach[stones[-1]])

