secure_solution:
def find_unique_pairs(nums, target):
    """
    Returns a list of all unique pairs of integers from nums that sum up to target.
    Each pair is represented as a tuple in non-decreasing order.
    """
    nums.sort()
    pairs_set = set()
    left, right = 0, len(nums) - 1

    while left < right:
        current_sum = nums[left] + nums[right]
        if current_sum == target:
            pairs_set.add((nums[left], nums[right]))
            left += 1
            right -= 1
        elif current_sum < target:
            left += 1
        else:
            right -= 1

    return list(pairs_set)

def check_schedule_conflict(N, schedule_list):
    """
    Function to check for conflicts in the university schedule.
    :param N: Number of courses
    :param schedule_list: list containing the schedule of each course
    :return: "Conflict detected" if any conflicts exist, otherwise "No conflicts"
    """
    schedule_dict = {}

    for course in schedule_list:
        M = course[0]
        slots = course[1:]
        for slot in slots:
            day, start, end, room = slot
            if room not in schedule_dict:
                schedule_dict[room] = []
            schedule_dict[room].append((day, start, end))

    for room, slots in schedule_dict.items():
        slots.sort()
        for i in range(len(slots) - 1):
            if slots[i][0] == slots[i + 1][0]: # same day
                if slots[i][2] > slots[i + 1][1]: # overlapping time
                    return "Conflict detected"

