from typing import List

def bubble_sort(arr: List[int], simulation: bool=False) -> List[int]:
    """
    Sorts an array of integers using the bubble sort algorithm.

    :param arr: List of integers to be sorted.
    :param simulation: When True, prints the array state after each swap operation.
    :return: Sorted list of integers in ascending order.
    """
    n = len(arr)
    if n <= 1:
        return arr

    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
                if simulation:
                    print(f"iteration {j + 1}: {' '.join(map(str, arr))}")
        if not swapped:
            break
    return arr

