def count_geometric_triplets(arr, d):
    """
    Returns the number of distinct triplets (i, j, k) such that arr[i], arr[j], and arr[k] form a geometric progression with common ratio d.
    """
    if d == 0:
        # Special case for d == 0
        count_zero = arr.count(0)
        return count_zero * (count_zero - 1) * (count_zero - 2) // 6

    count_i = {}
    count_k = {}
    triplets_count = 0

    for number in arr:
        count_k[number] = count_k.get(number, 0) + 1

    for j in range(len(arr)):
        number = arr[j]
        count_k[number] -= 1

        if number % d == 0:
            left = number // d
            right = number * d
            triplets_count += count_i.get(left, 0) * count_k.get(right, 0)

        count_i[number] = count_i.get(number, 0) + 1

    return triplets_count

def num_ways_to_reach_bottom_right_corner(n, m, grid):
    """
    Returns the number of different ways to move from the top-left corner to
    the bottom-right corner of a grid without stepping on cells marked with '#'.
    """
    # Initialize a 2D DP array with all zeros
    dp = [[0] * m for _ in range(n)]

    # Starting position
    dp[0][0] = 1

    # Fill the dp array
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][m-1]

