def arrange_students_circle(n, k):
    if n < 3 or k == 0 or k >= n:
        return "Not possible"

    if k % 2 == 1:
        return "Not possible"

    step = k // 2

    arrangement = list(range(1, n + 1))
    result = [-1] * n

    for i in range(n):
        result[i] = arrangement[(i + step) % n]

    return " ".join(map(str, result))

