def has_zero_sum_subset(n, arr):
    """
    Function to check if there exists a non-empty subset with sum equal to 0.

    :param n: Number of elements in the list
    :param arr: List of integers
    :return: "YES" if such a subset exists, otherwise "NO"
    """
    from itertools import combinations

    if n == 0:
        return "NO"

    # Check all possible non-empty subsets
    for i in range(1, n + 1):
        for subset in combinations(arr, i):
            if sum(subset) == 0:
                return "YES"

    return "NO"

