def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in the string s.
    If all characters repeat, returns '_'.
    """
    char_count = {}

    # First pass to count the occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass to find the first non-repeating character
    for char in s:
        if char_count[char] == 1:
            return char

    return '_'

