def can_satisfy_watering_conditions(m, n, house_requirements, pipes):
    # Create an adjacency list to store factory capacities connected to each house
    from collections import defaultdict

    house_to_factory_capacity = defaultdict(list)

    for h, f, c in pipes:
        house_to_factory_capacity[h].append(c)

    # Check if each house can connect to factories with required capacity
    for house in range(1, m + 1):
        house_capacity = sorted(house_to_factory_capacity[house], reverse=True)
        required_water = house_requirements[house - 1]

        # Sum capacities until we meet or exceed required_water
        supplied_water = 0
        for capacity in house_capacity:
            supplied_water += capacity
            if supplied_water >= required_water:
                break
        if supplied_water < required_water:
            return "NO"

    return "YES"

