def trap_water(elevation_map):
    n = len(elevation_map)
    if n == 0:
        return 0

    left_max = [0] * n
    right_max = [0] * n

    left_max[0] = elevation_map[0]
    for i in range(1, n):
        left_max[i] = max(left_max[i - 1], elevation_map[i])

    right_max[n - 1] = elevation_map[n - 1]
    for i in range(n - 2, -1, -1):
        right_max[i] = max(right_max[i + 1], elevation_map[i])

    water_trapped = 0
    for i in range(n):
        water_trapped += min(left_max[i], right_max[i]) - elevation_map[i]

    return water_trapped

