def find_pairs(arr, target):
    """
    Returns a list of unique pairs that sum up to the target.
    Each pair is in the form (a, b) where a <= b.
    """
    seen = set()
    output = set()

    for num in arr:
        complement = target - num
        if complement in seen:
            pair = (min(num, complement), max(num, complement))
            output.add(pair)
        seen.add(num)

    if output:
        return list(output)
    else:
        return "No pairs found"

