def max_subarray_with_two_distinct(nums):
    """
    Returns the length of the longest subarray that contains at most two distinct numbers such that
    the two distinct numbers appear consecutively.
    """
    if not nums:
        return 0

    max_length = 0
    left = 0
    num_count = {}

    for right in range(len(nums)):
        num = nums[right]
        if num in num_count:
            num_count[num] += 1
        else:
            num_count[num] = 1

        while len(num_count) > 2:
            left_num = nums[left]
            num_count[left_num] -= 1
            if num_count[left_num] == 0:
                del num_count[left_num]
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

