def combination_iterative(n, r):
    """
    Calculate nCr using an iterative dynamic programming approach.

    :param n: Total number of items
    :param r: Number of items to choose
    :return: The number of combinations (nCr)
    """
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1

    if r > n - r:
        r = n - r

    dp = [0] * (r + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        for j in range(min(r, i), 0, -1):
            dp[j] = dp[j] + dp[j - 1]

    return dp[r]

