def calculate_points(visitors):
    """
    Returns a list of visitors with their corresponding points based on height, 
    sorted by points in descending order and by name alphabetically in case of ties.
    """
    result = []

    for visitor in visitors:
        if visitor['height'] < 50:
            points = 0
        elif 50 <= visitor['height'] <= 60:
            points = 5
        elif 61 <= visitor['height'] <= 70:
            points = 10
        else:
            points = 15
        result.append({'name': visitor['name'], 'points': points})

    result.sort(key=lambda x: (-x['points'], x['name']))

    return result

