def can_select_subsequence(s):
    """
    Determines if Aria can select a subsequence in which the string cannot be made a palindrome.
    """

    # A string can always be rearranged to a palindrome if it contains at most one character with an odd count frequency.
    frequency = {}
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    odd_count = sum(1 for count in frequency.values() if count % 2 == 1)

    # If there are two or more characters with an odd frequency, it is impossible to rearrange them into a palindrome.
    if odd_count >= 2:
        return "YES"
    else:
        return "NO"

