def maximize_sum(arr1, arr2, d):
    """ 
    Maximizes the sum of elements in arr1 by swapping elements between arr1 and arr2
    with the condition that absolute difference between swapped elements is no more than d.
    """
    # Sorting both arrays
    arr1.sort()
    arr2.sort()

    # Finding if there are any possible beneficial swaps
    for i in range(len(arr1)):
        for j in range(len(arr2)):
            if abs(arr1[i] - arr2[j]) <= d and arr2[j] > arr1[i]:
                # Swap elements
                arr1[i], arr2[j] = arr2[j], arr1[i]

    return sum(arr1)

