def closest_three_sum(arr, target):
    """
    Finds the closest possible sum of any three distinct elements in `arr` to the `target`.
    """
    arr.sort()
    closest_sum = float('inf')

    for i in range(len(arr) - 2):
        left, right = i + 1, len(arr) - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == target:
                return current_sum  # If the exact sum is found, return it

            if abs(target - current_sum) < abs(target - closest_sum):
                closest_sum = current_sum
            elif abs(target - current_sum) == abs(target - closest_sum):
                closest_sum = min(closest_sum, current_sum)

            if current_sum < target:
                left += 1
            else:
                right -= 1

    return closest_sum

