    Returns the first character in the string s that does not repeat.
    If every character repeats, returns None.

    :param s: string
    :return: character or None
    """
    # Create a hash map to store frequency of each character
    char_count = {}

    # Fill the hash map with the frequency of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find and return the first unique character
    for char in s:
        if char_count[char] == 1:
