def find_unsorted_subarray(nums):
    """
    Returns the length of the shortest subarray, that when sorted, makes the entire list sorted in non-decreasing order.
    """
    n = len(nums)
    if n <= 1:
        return 0

    start, end = -1, -1
    max_val, min_val = float('-inf'), float('inf')

    for i in range(n):
        if nums[i] < max_val:
            end = i
        else:
            max_val = nums[i]

    for i in range(n-1, -1, -1):
        if nums[i] > min_val:
            start = i
        else:
            min_val = nums[i]

    if start == -1:
        return 0
    else:
        return end - start + 1

