def simulate_warehouse_robot(n, size, instructions):
    """
    Simulates the movement of a warehouse robot based on given instructions.

    Parameters:
    n (int): Number of instructions
    size (int): Maximum size of the grid (width and height)
    instructions (list): List of instruction strings

    Returns:
    (int, int): Final coordinates of the robot
    """
    x, y = 0, 0

    for instruction in instructions:
        action = instruction.split()

        if action[0] == 'U':
            y = min(y + int(action[1]), size - 1)
        elif action[0] == 'D':
            y = max(y - int(action[1]), 0)
        elif action[0] == 'L':
            x = max(x - int(action[1]), 0)
        elif action[0] == 'R':
            x = min(x + int(action[1]), size - 1)
        elif action[0] == 'P':
            x, y = int(action[1]), int(action[2])

    return (x, y)

