def final_position(commands):
    """
    Returns the final position of the robot after executing the given commands.

    Parameters:
    commands (str): A string of commands consisting of 'U', 'D', 'L', 'R'.

    Returns:
    tuple: A tuple (x, y) representing the final coordinates.
    """
    x, y = 0, 0

    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1

    return x, y

