def pair_sum_indices(array: List[int], target: int) -> Optional[Tuple[int, int]]:
    """
    Returns the indices of the two numbers in the array that add up to the target sum.
    Each input is assumed to have exactly one solution, and no element can be used twice.
    """
    lookup = {}
    for i, num in enumerate(array):
        complement = target - num
        if complement in lookup:
            return (lookup[complement], i)
        lookup[num] = i
    return None

