from typing import List

def max_sum_non_adjacent(nums: List[int]) -> int:
    if not nums:
        return 0
    if len(nums) == 1:
        return max(0, nums[0])

    include = 0  # max sum including the current element
    exclude = 0  # max sum excluding the current element

    for num in nums:
        new_exclude = max(exclude, include)
        include = exclude + num
        exclude = new_exclude

    return max(include, exclude)

