def make_smallest_palindrome(test_cases):
    results = []

    for t in test_cases:
        N, S = t
        S = list(S)
        changed = False

        # Check if it's already a palindrome
        if S == S[::-1]:
            results.append("".join(S))
            continue

        for i in range(N // 2):
            if S[i] != S[N - i - 1]:
                if changed:
                    results.append("impossible")
                    break
                if S[i] < S[N - i - 1]:
                    S[N - i - 1] = S[i]
                    changed = True
                else:
                    S[i] = S[N - i - 1]
                    changed = True
        else:
            # double-check for lexicographically smallest
            if S != S[::-1]:
                results.append("impossible")
            else:
                results.append("".join(S))

    return results

