def max_sum_contiguous_subarray(nums, k):
    """
    Finds the maximum sum of a contiguous subarray with at most `k` elements.
    Returns a tuple of the maximum sum and the subarray.
    """
    n = len(nums)
    if n == 0:
        return (0, [])

    max_sum = float('-inf')
    current_sum = 0
    start = 0

    for end in range(n):
        current_sum += nums[end]

        # Check if the current subarray length exceeds k
        if end - start + 1 > k:
            current_sum -= nums[start]
            start += 1

        if current_sum > max_sum:
