def can_form_palindrome(s):
    """
    Returns "YES" if the input string can be rearranged to form a palindrome, otherwise returns "NO".
    """
    # Count frequency of each character
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

    # Track the number of characters that appear an odd number of times
    odd_count = sum(1 for count in freq.values() if count % 2 != 0)

    # A string can form a palindrome if it has at most one character with an odd frequency
    return "YES" if odd_count <= 1 else "NO"

