secure_solution:
def lexicographically_smallest_string(s):
    """
    Finds the lexicographically smallest string obtainable by sorting any substring of s once.
    """
    n = len(s)
    sorted_s = sorted(s)

    # Find the first position where the original string differs from the sorted string
    for i in range(n):
        if s[i] != sorted_s[i]:
            break
    else:
        # If no such position is found, the string is already fully sorted
        return s

    # Find the last position from the end where the original string differs from the sorted string
    for j in range(n-1, -1, -1):
        if s[j] != sorted_s[j]:
            break

    # Create the new string by sorting the substring s[i:j+1]
    return s[:i] + ''.join(sorted(s[i:j+1])) + s[j+1:]

