def min_operations_to_sort_deck(n, perm):
    """
    Returns the minimum number of operations required to sort the deck in ascending order.
    """
    sorted_perm = sorted(perm)

    if perm == sorted_perm:
        return 0

    # Check if we can sort by one reverse
    for i in range(n):
        for j in range(i + 1, n):
            new_perm = perm[:i] + perm[i:j+1][::-1] + perm[j+1:]
            if new_perm == sorted_perm:
                return 1

    # If can't be done with one reverse, then check if can be done with one swap
    for i in range(n):
        for j in range(i + 1, n):
            new_perm = perm[:i] + [perm[j]] + perm[i+1:j] + [perm[i]] + perm[j+1:]
            if new_perm == sorted_perm:
                return 1

    # Otherwise, it can be done with at most 2 operations
    return 2

