def remove_duplicate_letters(s):
    """
    Returns the smallest lexicographical string that can be obtained by removing 
    duplicate letters from the input string `s`.
    """
    stack = []
    seen = set()
    last_occurrence = {char: index for index, char in enumerate(s)}

    for index, char in enumerate(s):
        if char not in seen:
            while stack and char < stack[-1] and index < last_occurrence[stack[-1]]:
                seen.remove(stack.pop())
            stack.append(char)
            seen.add(char)

    return ''.join(stack)

