def find_longest_balanced_substring(s):
    """
    Returns the longest balanced substring containing equal number of 'a's and 'b's.
    If multiple longest balanced substrings exist, returns the first one.
    If no balanced substring exists, returns an empty string.
    """
    max_len = 0
    max_substr_start = -1

    for i in range(len(s)):
        count_a = 0
        count_b = 0
        for j in range(i, len(s)):
            if s[j] == 'a':
                count_a += 1
            else:
                count_b += 1

            if count_a == count_b:
                if (j - i + 1) > max_len:
                    max_len = j - i + 1
                    max_substr_start = i

    if max_len > 0:
        return s[max_substr_start:max_substr_start + max_len]
    return ""

