def min_moves(N: int, K: int) -> int:
    # Create a table to store the results of subproblems
    egg_floor = [[0 for x in range(N + 1)] for x in range(K + 1)]

    # Base case: With one egg, we need i trials at worst-case for i floors
    for i in range(1, N + 1):
        egg_floor[1][i] = i

    for e in range(2, K + 1):
        for f in range(1, N + 1):
            egg_floor[e][f] = float('inf')
            for x in range(1, f + 1):
                res = 1 + max(egg_floor[e - 1][x - 1], egg_floor[e][f - x])
                if res < egg_floor[e][f]:
                    egg_floor[e][f] = res

    return egg_floor[K][N]

