def lexicographically_smallest_string(s):
    """
    Returns the lexicographically smallest string that can be obtained by at most one reversal of a contiguous substring.
    """
    n = len(s)
    min_str = s
    for i in range(n):
        for j in range(i+1, n+1):
            reversed_substr = s[:i] + s[i:j][::-1] + s[j:]
            if reversed_substr < min_str:
                min_str = reversed_substr
    return min_str

