def min_students_to_remove(heights):
    """
    Returns the minimum number of students that need to be removed
    so that each student can see the board.
    """
    if not heights:
        return 0

    n = len(heights)
    dp = [1] * n  # dp[i] will be the length of the longest non-decreasing subsequence ending at i

    for i in range(1, n):
        for j in range(i):
            if heights[i] >= heights[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    max_len = max(dp)
    return n - max_len

