    results = []
    for case in test_cases:
        n = case[0]
        max_slots = case[1:]
        assignment = []
        for pos, max_slot in enumerate(max_slots, start=1):
            found = False
            for time_slot in range(pos, max_slot + 1, pos):
                if time_slot % pos == 0:
                    assignment.append(time_slot)
                    found = True
                    break
            if not found:
                assignment.append(-1)
        results.append(assignment)
    return results

