def min_total_price_with_discount(n, prices):
    """
    Returns the minimum possible price for buying any two different novels after applying a 100 yen discount.
    """
    min_price = float('inf')

    # Check all pairs of novels
    for i in range(n):
        for j in range(i + 1, n):
            total_price = prices[i] + prices[j] - 100
            if total_price < min_price:
                min_price = total_price

    return min_price

