def special_groups_count(N, D, grades):
    count = 0
    # Iterate over all possible 2^N-1 subsets (non-empty)
    for i in range(1, 1 << N):
        current_set = []
        for j in range(N):
            if i & (1 << j):
                current_set.append(grades[j])
        if max(current_set) - min(current_set) <= D:
            count += 1
    return count

