        user_friends_set.update(circle)

    recommended_friends_set = set()

    # Process each friend and their friends of friends
    for fof in friends_of_friends:
        friend_id = fof[0]
        friends_of_friend = fof[1:]

        for friend in friends_of_friend:
            if friend not in user_friends_set:
                recommended_friends_set.add(friend)

    recommended_friends_list = sorted(recommended_friends_set)
    return recommended_friends_list

