def countEqualSubstrings(s):
    """
    Returns the number of substrings with equal numbers of 0s and 1s.
    """
    count = 0
    prev_run_length = 0
    current_run_length = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            current_run_length += 1
        else:
            prev_run_length = current_run_length
            current_run_length = 1
        if prev_run_length >= current_run_length:
            count += 1

    return count

