from datetime import datetime, timedelta

def detect_suspicious_activity(m, k, n, logs):
    user_logs = defaultdict(list)
    flagged_users = set()

    # Parse logs and store them by username
    for log in logs:
        timestamp_str, username = log[:16], log[17:]
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M")
        user_logs[username].append(timestamp)

    # Check each user's activity for suspicious behavior
    for username, timestamps in user_logs.items():
        timestamps.sort()
        for i in range(len(timestamps)):
            window_start = timestamps[i]
            window_end = window_start + timedelta(minutes=m)
            count = 0
            for j in range(i, len(timestamps)):
                if timestamps[j] > window_end:
                    break
                count += 1
            if count > k:
                flagged_users.add(username)
                break

    # Output flagged users in alphabetical order
    if flagged_users:
        return sorted(flagged_users)
    else:
        return ["None"]

