def count_arithmetic_triplets(n, sequence):
    """
    Returns the number of triplets in the sequence that form an arithmetic progression.
    """
    count = 0
    for i in range(n - 2):
        if sequence[i + 1] - sequence[i] == sequence[i + 2] - sequence[i + 1]:
            count += 1
    return count

