def can_ensure_no_same_adjacent_heights(N, D, heights):
    """
    Returns "YES" if it's possible to arrange the tree heights such that no two adjacent
    heights are the same after D days, otherwise returns "NO".
    """
    # If all heights are already unique, return YES immediately
    if len(set(heights)) == N:
        return "YES"

    # If any two adjacent trees have the same initial height
    for i in range(N - 1):
        if heights[i] == heights[i + 1]:
            number_same_height_adjacent_pairs = sum(1 for i in range(N - 1) if heights[i] == heights[i + 1])
            if D >= number_same_height_adjacent_pairs:
                return "YES"
            else:
                return "NO"

    # If we can safely make adjacent heights different, return YES
    return "YES"

