def shortest_string_length(s):
    """
    Determines the length of the shortest string that can be obtained
    by removing adjacent pairs of the same character.

    :param s: str - input string consisting of lowercase English letters
    :return: int - length of the shortest string that can be obtained
    """
    stack = []

    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)

    return len(stack)

