def organize_string(s):
    """
    Organizes the input string into blocks that start with a digit and contain one lowercase letter.
    If it is not possible to create valid blocks, returns "Impossible".
    """
    digits = [ch for ch in s if ch.isdigit()]
    letters = [ch for ch in s if ch.islower()]

    if len(digits) != len(letters):
        return "Impossible"

    blocks = []
    for i in range(len(digits)):
        blocks.append(digits[i] + letters[i])

    return "\n".join(blocks)

