def minimum_swaps_to_sort_books(n, widths):
    """
    Returns the minimum number of adjacent swaps required to sort book widths in non-decreasing order.
    """
    swaps = 0
    # Bubble sort to count swaps
    for i in range(n):
        for j in range(0, n-i-1):
            if widths[j] > widths[j+1]:
                # Swap and count
                widths[j], widths[j+1] = widths[j+1], widths[j]
                swaps += 1
    return swaps

