import heapq

def minimum_latency(n, m, edges, S, D):
    # Create the graph as an adjacency list
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, l in edges:
        graph[u].append((v, l))
        graph[v].append((u, l))

    # Dijkstra's algorithm to find the shortest path from S to D
    heap = [(0, S)]
    visited = set()
    min_latency = {i: float('inf') for i in range(1, n + 1)}
    min_latency[S] = 0

    while heap:
        current_latency, current_node = heapq.heappop(heap)

        if current_node in visited:
            continue

        visited.add(current_node)

        if current_node == D:
            return current_latency

        for neighbor, latency in graph[current_node]:
            if neighbor not in visited:
                new_latency = current_latency + latency
                if new_latency < min_latency[neighbor]:
                    min_latency[neighbor] = new_latency
                    heapq.heappush(heap, (new_latency, neighbor))

    return -1 if min_latency[D] == float('inf') else min_latency[D]

