def maximize_battery_energy(R, C, M, X, grid):
    total_energy = sum(sum(row) for row in grid)

    # Flatten the grid to a list of cells
    cells = [grid[r][c] for r in range(R) for c in range(C)]

    # Sort cells based on their values in descending order
    cells.sort(reverse=True)

    # Add the additional energy using M operations each increasing energy by X
    for i in range(M):
        cells[i % (R * C)] += X

    return sum(cells)

