def group_by_range(nums):
    """
    Groups integers by 1-10, 11-20, etc. 
    Only returns lists for ranges that have numbers.
    """
    if not nums:
        return []

    range_dict = {}

    for num in nums:
        if num < 1:
            continue
        range_key = (num - 1) // 10
        if range_key not in range_dict:
            range_dict[range_key] = []
        range_dict[range_key].append(num)

    result = [range_dict[key] for key in sorted(range_dict)]
    return result

