def longest_zero_sum_subsequence(arr):
    prefix_sum = 0
    prefix_sum_indices = {}  # stores the first occurrence of each prefix sum
    max_length = 0

    for i, num in enumerate(arr):
        prefix_sum += num

        if prefix_sum == 0:
            max_length = i + 1
        if prefix_sum in prefix_sum_indices:
            max_length = max(max_length, i - prefix_sum_indices[prefix_sum])
        else:
            prefix_sum_indices[prefix_sum] = i

    return max_length

