def subarray_sum(nums, target):
    """
    Returns the number of continuous subarrays which sum up to the target.
    """
    count = 0
    current_sum = 0
    prefix_sums = {0: 1}

    for num in nums:
        current_sum += num
        if (current_sum - target) in prefix_sums:
            count += prefix_sums[current_sum - target]
        prefix_sums[current_sum] = prefix_sums.get(current_sum, 0) + 1

    return count

def max_even_number(s):
    """
    Returns the maximum possible even number that can be formed using all digits of the string exactly once.
    If it is not possible to form an even number, returns -1.
    """
    digits = sorted(s, reverse=True)

    # Try to find an even digit to place at the end
    for i in range(len(digits) - 1, -1, -1):
        if int(digits[i]) % 2 == 0:
            # Swap the found even digit to the end
            digits.append(digits.pop(i))
            return ''.join(digits)

    return '-1'

