import heapq

def min_cost_to_buy_k_items(prices, k, discounts):
    discounted_prices = []

    # Apply the discounts
    for li, ri, ai, bi in discounts:
        for i in range(li, ri + 1):
            adjusted_price = prices[i] * (1 - bi / 100)
            discounted_prices.append(adjusted_price)

    # Add non-discounted prices as well
    for i in range(len(prices)):
        if not any(li <= i <= ri for li, ri, ai, bi in discounts):
            discounted_prices.append(prices[i])

    if len(discounted_prices) < k:
        return -1

    # Get the smallest k prices
    heapq.heapify(discounted_prices)
    total_cost = 0
    for _ in range(k):
        total_cost += heapq.heappop(discounted_prices)

    return total_cost

