secure_solution:
def min_removals_to_decreasing(nums):
    n = len(nums)
    # If the array is empty or has one element, it is already sorted in strictly decreasing order
    if n <= 1:
        return 0

    # Longest Decreasing Subsequence (LDS) array
    lds = [1] * n

    # Compute LDS values in reverse order
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if nums[i] > nums[j]:
                lds[i] = max(lds[i], 1 + lds[j])

    # The reason we subtract the length of the longest decreasing subsequence from total elements
    longest_decreasing_subsequence_length = max(lds)

    return n - longest_decreasing_subsequence_length

