def sum_of_divisors(number: int) -> int:
    """
    Return the sum of all positive divisors of the given number.

    :param number: A non-negative integer.
    :return: Sum of all positive divisors of the given number.
    :raises ValueError: If the input number is negative.
    """
    if number < 0:
        raise ValueError("The number must be non-negative.")

    if number == 0:
        return 0

    total = 0
    sqrt_num = int(number**0.5)

    for i in range(1, sqrt_num + 1):
        if number % i == 0:
            total += i
            if i != number // i:
                total += number // i

    return total

