def mergeStrings(word1, word2):
    """
    Returns the lexicographically smallest merge of `word1` and `word2`.
    """
    i, j = 0, 0
    merge = []

    while i < len(word1) and j < len(word2):
        if word1[i:] < word2[j:]:
            merge.append(word1[i])
            i += 1
        else:
            merge.append(word2[j])
            j += 1

    merge.extend(word1[i:])
    merge.extend(word2[j:])

    return ''.join(merge)

