def max_path_sum(N, matrix):
    if N == 0 or not matrix:
        return 0
    # Create a DP array to store the maximum sum up to each cell
    dp = [[0] * N for _ in range(N)]

    dp[0][0] = matrix[0][0]

    # Fill the first row
    for j in range(1, N):
        dp[0][j] = dp[0][j-1] + matrix[0][j]

    # Fill the first column
    for i in range(1, N):
        dp[i][0] = dp[i-1][0] + matrix[i][0]

    # Fill the remaining cells
    for i in range(1, N):
        for j in range(1, N):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    return dp[N-1][N-1]

