from collections import deque

def min_moves(grid):
    """
    Finds the minimum number of moves required to traverse from the top-left
    corner of the grid to the bottom-right corner with given movement constraints.
    """
    if not grid or not grid[0]:
        return -1

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    start = (0, 0)
    end = (rows - 1, cols - 1)

    if start == end:
        return 0

    queue = deque([(0, 0, 0)])  # (row, col, distance)
    visited = set()
    visited.add((0, 0))

    while queue:
        row, col, dist = queue.popleft()

        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                if grid[nr][nc] <= grid[row][col] + 1:
                    if (nr, nc) == end:
                        return dist + 1
                    queue.append((nr, nc, dist + 1))
                    visited.add((nr, nc))

    return -1

