from collections import deque

def min_moves(n, m, k, grid):
    if grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return -1

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    queue = deque([(0, 0, 0, 0)])  # (x, y, moves, used_booster)
    visited = set([(0, 0, 0)])  # (x, y, used_booster)

    while queue:
        x, y, moves, used_booster = queue.popleft()

        if x == n-1 and y == m-1:
            return moves

        for dx, dy in directions:
            for step in range(1, (k if not used_booster else 1) + 1):
                nx, ny = x + dx*step, y + dy*step
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == 0:
                    new_booster = used_booster or step > 1
                    if (nx, ny, new_booster) not in visited:
                        visited.add((nx, ny, new_booster))
                        queue.append((nx, ny, moves + 1, new_booster))
                else:
                    break

    return -1

