def longest_unique_substring(s):
    """
    Returns the longest substring of `s` that contains only unique characters.
    If there are ties, the first one that appears is returned.
    """
    if not s:
        return ""

    start, max_len, max_sub = 0, 0, ""
    char_index_map = {}

    for end in range(len(s)):
