def first_unique_char(s):
    """
    Returns the index of the first unique character in the string `s`.
    If there are no unique characters, returns -1.
    The function is case-sensitive.
    """
    # Dictionary to store frequency of each character
    char_count = {}

    # Traverse the string to fill the char_count
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Traverse the string again to find the first unique character
    for index, char in enumerate(s):
        if char_count[char] == 1:
            return index

    # If no unique character is found
    return -1

