def smallest_segment_length(resources):
    """
    Returns the length of the smallest segment that contains at least one 'G', one 'S', and one 'C'.
    If no such segment exists, return 0.
    """
    n = len(resources)
    if n < 3:
        return 0

    min_length = float('inf')
    left = 0
    count = {'G': 0, 'S': 0, 'C': 0}
    distinct_count = 0

    for right in range(n):
        if resources[right] in count:
            if count[resources[right]] == 0:
                distinct_count += 1
            count[resources[right]] += 1

        while distinct_count == 3:
            min_length = min(min_length, right - left + 1)
            if resources[left] in count:
                count[resources[left]] -= 1
                if count[resources[left]] == 0:
                    distinct_count -= 1
            left += 1

    return min_length if min_length != float('inf') else 0

