def round_grades(grades):
    """
    Rounds grades according to the university policy.

    Parameters:
    grades (list of int): List of integer grades before rounding.

    Returns:
    list of int: List of integer grades after rounding.
    """
    rounded_grades = []
    for grade in grades:
        if grade < 38:
            rounded_grades.append(grade)
        else:
            next_multiple_of_5 = ((grade // 5) + 1) * 5
            if next_multiple_of_5 - grade < 3:
                rounded_grades.append(next_multiple_of_5)
            else:
                rounded_grades.append(grade)
    return rounded_grades

