def longest_repeated_subsequence(n, s):
    """
    Returns the length of the longest subsequence that repeats itself twice non-overlapping in the string s.
    """
    # Create a 2D DP array of size (n+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if s[i - 1] == s[j - 1] and i != j:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][n]

