secure_solution:
def max_profit(prices, k):
    """
    Returns the maximum profit that can be achieved with at most `k` transactions.
    """
    if not prices:
        return 0

    n = len(prices)
    if k >= n // 2:
        # Simplified case: Best time to buy and sell stocks II logic
        profit = 0
        for i in range(1, n):
            if prices[i] > prices[i - 1]:
                profit += prices[i] - prices[i - 1]
        return profit

    # Initialize dp table
    dp = [[0] * n for _ in range(k + 1)]

    for t in range(1, k + 1):
        max_diff = -prices[0]
        for d in range(1, n):
            dp[t][d] = max(dp[t][d - 1], prices[d] + max_diff)
            max_diff = max(max_diff, dp[t - 1][d] - prices[d])

    return dp[k][-1]

