def min_number_of_subsequences(n, sequence):
    if n == 0:
        return 0

    subsequences_count = 1
    last_number = sequence[0]

    for i in range(1, n):
        if sequence[i] <= last_number:
            subsequences_count += 1
            last_number = sequence[i]
