secure_solution:
def generate_friendly_sequence(N, M):
    """
    Generates a Friendly Sequence of length N with elements between 1 and M, inclusive.
    Returns a string of space-separated integers or "-1" if no such sequence is possible.
    """
    if M < 2:
        return "-1"

    # Start with 2, which is guaranteed to have multiple values with gcd > 1
    sequence = [2 * i for i in range(1, N + 1) if 2 * i <= M]

    # Check if we have enough elements
    if len(sequence) < N:
        return "-1"

    return ' '.join(map(str, sequence[:N]))

