secure_solution:
def min_swaps_to_group_ones(bits):
    """
    Returns the minimum number of swaps needed to group all "1"s together in a contiguous block.
    """
    num_ones = bits.count("1")

    if num_ones == 0:
        return -1

    num_bits = len(bits)
    min_swaps = float('inf')
    ones_count_in_window = 0
    left = 0

    for right in range(num_bits):
        if bits[right] == "1":
            ones_count_in_window += 1

        if right - left + 1 == num_ones:
            min_swaps = min(min_swaps, num_ones - ones_count_in_window)
            if bits[left] == "1":
                ones_count_in_window -= 1
            left += 1

    return min_swaps

