    """
    Determines if the given list of words can form a word square.
    """
    if not words:
        return False

    num_words = len(words)
    word_length = len(words[0])

    if word_length != num_words:
        return False

    for i in range(num_words):
        for j in range(word_length):
            if words[i][j] != words[j][i]:
