def longest_increasing_subsequence(poles):
    """
    Returns the length of the longest strictly increasing subsequence of poles.
    """
    import bisect
    if not poles:
        return 0

    lis = []
    for height in poles:
        pos = bisect.bisect_left(lis, height)
        if pos == len(lis):
            lis.append(height)
        else:
            lis[pos] = height

    return len(lis)

