def four_sum(nums, target):
    """
    Returns all unique quadruplets [nums[a], nums[b], nums[c], nums[d]] 
    such that:
    0 <= a, b, c, d < len(nums)
    a, b, c, and d are all distinct.
    nums[a] + nums[b] + nums[c] + nums[d] == target

    :param List[int] nums: List of integers
    :param int target: The target sum
    :return List[List[int]]: List of unique quadruplets
    """
    nums.sort()
    quadruplets = []
    n = len(nums)

    for i in range(n-3):
        if i > 0 and nums[i] == nums[i-1]:
            continue
        for j in range(i+1, n-2):
            if j > i+1 and nums[j] == nums[j-1]:
                continue
            left, right = j + 1, n - 1
            while left < right:
                current_sum = nums[i] + nums[j] + nums[left] + nums[right]
                if current_sum == target:
                    quadruplets.append([nums[i], nums[j], nums[left], nums[right]])
                    while left < right and nums[left] == nums[left + 1]:
                        left += 1
                    while left < right and nums[right] == nums[right - 1]:
                        right -= 1
                    left += 1
                    right -= 1
                elif current_sum < target:
                    left += 1
                else:
                    right -= 1

    return quadruplets

