import heapq

def minimum_travel_time(n, m, roads):
    if not roads and n > 1:
        return -1  # if there are no roads and more than one intersection, it's impossible

    # Create an adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v, w in roads:
        adj[u].append((w, v))
        adj[v].append((w, u))

    # Use Prim's algorithm to find Minimum Spanning Tree (MST)
    min_cost = 0
    in_mst = [False] * (n + 1)
    min_heap = [(0, 1)]  # (cost, start_vertex), use vertex 1 as the starting point

    while min_heap:
        cost, u = heapq.heappop(min_heap)
        if in_mst[u]:
            continue
        min_cost += cost
        in_mst[u] = True
        for edge_cost, v in adj[u]:
            if not in_mst[v]:
                heapq.heappush(min_heap, (edge_cost, v))

    # If not all intersections are included in the MST
    if not all(in_mst[1:]):
        return -1

    return min_cost

