from collections import deque

def min_steps_to_nearest_path(maze):
    rows, cols = len(maze), len(maze[0])

    # Find the starting point
    start = None
    for r in range(rows):
        for c in range(cols):
            if maze[r][c] == 2:
                start = (r, c)
                break
        if start:
            break

    if not start:
        return -1  # No starting point found

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    queue = deque([(start[0], start[1], 0)]) # (row, col, steps)

    while queue:
        r, c, steps = queue.popleft()

        # Check if we hit a walkable path
        if maze[r][c] == 0:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and maze[nr][nc] != 1:
                visited.add((nr, nc))
                queue.append((nr, nc, steps + 1))

    return -1  # No walkable path found

