from typing import Union, Tuple
import math

def solve_quadratic(a: float, b: float, c: float) -> Union[Tuple[float, float], Tuple[float], str]:
    if a == 0 and b == 0 and c == 0:
        raise ValueError('At least one coefficient must be non-zero.')

    if a == 0:  # Handle linear case bx + c = 0
        if b == 0:
            return "No Real Roots"
        return (-c / b,)

    discriminant = b**2 - 4*a*c

    if discriminant > 0:
        root1 = (-b + math.sqrt(discriminant)) / (2 * a)
        root2 = (-b - math.sqrt(discriminant)) / (2 * a)
        return (root1, root2)
    elif discriminant == 0:
        root = -b / (2 * a)
        return (root,)
    else:
        return "No Real Roots"

