def subtractOne(digits):
    """
    Subtracts one from the number represented by the digits array.
    """
    n = len(digits)

    # Start from the end of the array
    for i in range(n-1, -1, -1):
        if digits[i] > 0:
            digits[i] -= 1
            break
        else:
            digits[i] = 9

    # If the first element is zero and the array length is greater than 1, remove it
    if digits[0] == 0 and len(digits) > 1:
        digits.pop(0)

    return digits

