def rearrange_parity(N, arr):
    """
    Rearranges the array such that no two adjacent integers have the same parity.
    Returns the rearranged array or -1 if not possible.
    """
    odds = [x for x in arr if x % 2 == 1]
    evens = [x for x in arr if x % 2 == 0]

    if abs(len(odds) - len(evens)) > 1:
        return -1

    # Interleave odds and evens
    result = []
    if len(odds) > len(evens):
        for i in range(len(evens)):
            result.append(odds[i])
            result.append(evens[i])
        result.append(odds[-1])
    elif len(evens) > len(odds):
        for i in range(len(odds)):
            result.append(evens[i])
            result.append(odds[i])
        result.append(evens[-1])
    else:
        for i in range(len(odds)):
            result.append(odds[i])
            result.append(evens[i])

    return result

from collections import deque

def minimum_moves(w, h, grid, sx, sy, tx, ty):
    if not (0 <= sx < w and 0 <= sy < h and 0 <= tx < w and 0 <= ty < h):
        return -1
    if grid[sy][sx] == '#' or grid[ty][tx] == '#':
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(sx, sy, 0)])  # (x, y, distance)
    visited = set((sx, sy))

    while queue:
        x, y, dist = queue.popleft()
        if x == tx and y == ty:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in visited and grid[ny][nx] == '.':
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

