def find_peak_and_trough(arr):
    """
    Function to find the indices of one peak and one trough in the sequence, if they exist.
    """
    n = len(arr)

    peak = None
    trough = None

    for i in range(1, n-1):
        if arr[i] > arr[i-1] and arr[i] > arr[i+1]:
            peak = i
        if arr[i] < arr[i-1] and arr[i] < arr[i+1]:
            trough = i
        if peak is not None and trough is not None:
            break

    return peak, trough

