def min_insertions_to_avoid_adjacent_duplicates(T, cases):
    """
    Returns the minimum number of insertions needed to transform the strings in `cases` 
    such that no two adjacent characters are the same.
    """
    results = []
    for S in cases:
        count_inserts = 0
        for i in range(len(S) - 1):
            if S[i] == S[i + 1]:
                count_inserts += 1
        results.append(count_inserts)
    return results

