def smallest_character_twice(s, queries):
    """
    For each query, determine the lexicographically smallest character 
    that appears at least twice in the specified substring.
    """
    results = []
    for l_i, r_i in queries:
        substring = s[l_i-1:r_i]
        frequency = {}
        for char in substring:
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1

        smallest_char = '-1'
        for char in sorted(frequency.keys()):
            if frequency[char] > 1:
                smallest_char = char
                break

        results.append(smallest_char)

    return results

