def max_magical_value(grid):
    n = len(grid)
    m = len(grid[0])

    dp = [[0] * m for _ in range(n)]
    dp[0][0] = grid[0][0]

    # Initialize the first row and first column
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + grid[i][0]
    for j in range(1, m):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill the dp table
    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[-1][-1]

