def longest_common_difference_subsequence(n, sequence):
    """
    Returns the length of the longest subsequence where the difference between 
    consecutive elements is the same and as small as possible.
    """
    if n == 1:
        return 1

    longest_length = 1

    for i in range(n):
        for j in range(i + 1, n):
            diff = sequence[j] - sequence[i]
            current_length = 2
            last_value = sequence[j]

            for k in range(j + 1, n):
                if sequence[k] - last_value == diff:
                    current_length += 1
                    last_value = sequence[k]

            longest_length = max(longest_length, current_length)

    return longest_length

