def min_changes_to_good(s):
    """
    Returns the minimum number of character changes needed to make the string s a "good" string.
    A "good" string is defined as a string where no two adjacent characters are the same.
    """
    changes = 0
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            changes += 1
    return changes

