def longest_zero_sum_subarray(nums):
    prefix_sum_to_index = {}
    prefix_sum = 0
    max_length = 0

    for index, num in enumerate(nums):
        prefix_sum += num

        if prefix_sum == 0:
            max_length = index + 1
        if prefix_sum in prefix_sum_to_index:
            subarray_length = index - prefix_sum_to_index[prefix_sum]
            if subarray_length > max_length:
                max_length = subarray_length
        else:
            prefix_sum_to_index[prefix_sum] = index

    return max_length

