def max_positive_subarray_sum(arr):
    """
    Find the maximum sum of a contiguous subarray that does not contain any negative numbers.
    """
    max_sum = 0
    current_sum = 0

    for num in arr:
        if num >= 0:
            current_sum += num
            max_sum = max(max_sum, current_sum)
        else:
            current_sum = 0

    return max_sum

def max_sum_of_positive_subarray(T, test_cases):
    results = []
    for i in range(T):
        N = test_cases[i][0]
        difficulties = test_cases[i][1]
        maximum_sum = 0
        current_sum = 0

        for difficulty in difficulties:
            current_sum += difficulty
            if current_sum > maximum_sum:
                maximum_sum = current_sum
            if current_sum < 0:
                current_sum = 0

        results.append(maximum_sum)

    return results

def count_battleships(grid):
    """
    This function returns the total number of complete battleships in the grid.
    Battleships are continuous 'B's either horizontally or vertically.
    """
    if not grid:
        return 0

    N = len(grid)
    M = len(grid[0])
    count = 0

    for i in range(N):
        for j in range(M):
            if grid[i][j] == 'B':
                # Check if this 'B' is the start of a horizontal or vertical battleship
                if (i == 0 or grid[i-1][j] == '.') and (j == 0 or grid[i][j-1] == '.'):
                    count += 1

    return count

