def count_divisible_pairs(nums, k):
    """
    Returns the number of unique pairs (i, j) such that 0 <= i < j < len(nums)
    and nums[i] + nums[j] is divisible by a positive integer k.
    """
    count = 0
    n = len(nums)

    # Iterate over all pairs (i, j)
    for i in range(n):
        for j in range(i + 1, n):
            if (nums[i] + nums[j]) % k == 0:
                count += 1

    return count

