def shortest_distance_to_open_space(N, grid):
    from collections import deque

    # Initialize a result collector for buildings
    results = []

    # Initialize BFS structure
    queue = deque()
    visited = [[False] * N for _ in range(N)]

    # Enqueue all open spaces with initial distance 0
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 'O':
                queue.append((i, j, 0))
                visited[i][j] = True

    # Directions for moving in the grid (left, right, up, down)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS to find shortest distance from any open space to any building
    while queue:
        x, y, distance = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and not visited[nx][ny]:
                if grid[nx][ny] == 'B':
                    results.append(distance + 1)
                else:
                    queue.append((nx, ny, distance + 1))
                visited[nx][ny] = True

    return results

