def min_steps_to_reduce_to_zero(n):
    """
    Function to calculate the minimum number of steps to reduce n to 0.
    """
    steps = 0
    while n > 0:
        if n % 2 == 0:
            n //= 2
        else:
            n -= 1
        steps += 1
    return steps

