def find_sum_pairs(nums, target):
    """
    Returns all pairs of indices whose elements sum up to the target.

    :param nums: List[int], list of distinct integers
    :param target: int, target sum
    :return: List[Tuple[int, int]], list of pairs of indices
    """
    pairs = []
    num_indices = {num: idx for idx, num in enumerate(nums)}

    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_indices and num_indices[complement] != i:
            j = num_indices[complement]
            if i < j:
                pairs.append((i, j))

    return pairs

