def max_valley_trees(n, heights):
    if n < 3:
        return 0

    left = [1] * n
    right = [1] * n

    # Calculate the longest decreasing subsequence length from left to right
    for i in range(1, n):
        if heights[i] < heights[i - 1]:
            left[i] = left[i - 1] + 1

    # Calculate the longest increasing subsequence length from right to left
    for i in range(n - 2, -1, -1):
        if heights[i] < heights[i + 1]:
            right[i] = right[i + 1] + 1

    max_valley_length = 0

    # Find the maximum valley length
    for i in range(n):
        if left[i] > 1 and right[i] > 1:
            max_valley_length = max(max_valley_length, left[i] + right[i] - 1)

    return max_valley_length

