def most_frequent_letter(phrases):
    """
    Takes a list of phrases and returns the most frequent letter
    from each phrase. If there are multiple letters with the same highest frequency,
    the lexicographically smallest letter among them is returned.
    """
    results = []

    for phrase in phrases:
        # Create a dictionary to count the frequency of each letter
        frequency = {}
        for letter in phrase:
            if letter in frequency:
                frequency[letter] += 1
            else:
                frequency[letter] = 1

        # Find the maximum frequency
        max_frequency = max(frequency.values())

        # Identify all letters with the maximum frequency
        max_letters = [letter for letter in frequency if frequency[letter] == max_frequency]

        # Find the lexicographically smallest letter among those with the maximum frequency
        most_frequent = min(max_letters)

        results.append(most_frequent)

    return results

