def find_winner(s: str) -> str:
    """
    Determines the game winner (Alex or Jamie) based on the input string.

    Parameters:
    s (str): The input string consisting of lowercase English letters.

    Returns:
    str: "Alex" if Alex wins, "Jamie" if Jamie wins.
    """
    # Count the frequency of each character
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Determine number of characters that appear more than once
    more_than_once = sum(1 for count in char_count.values() if count > 1)

    # If there are more than one character that repeats, Alex wins
    if more_than_once > 0:
        return "Alex"
    else:
        return "Jamie"

