import re
from collections import defaultdict

def find_most_mentioned_handle(n, comments):
    mention_count = defaultdict(int)

    for comment in comments:
        mentions = re.findall(r'@(\w+)', comment)
        for mention in mentions:
            mention_count[mention] += 1

    most_mentioned_handle = min((handle for handle, count in mention_count.items() 
                                 if count == max(mention_count.values())), 
                                key=lambda h: h)

    return most_mentioned_handle

