def autocomplete(words, prefix):
    """
    Returns a list of words from the given list that start with the given prefix in lexicographical order.
    If no such words exist, returns ["NO SUGGESTIONS"].
    """
    # Filter the words that start with the given prefix
    suggestions = [word for word in words if word.startswith(prefix)]

    # Sort the words lexicographically and return the result
    if suggestions:
        return sorted(suggestions)
    else:
        return ["NO SUGGESTIONS"]

