def three_sum_exists(arr, target):
    """
    Determines if there are three distinct elements in the list that sum up to the target.

    :param arr: List of integers
    :param target: Integer target sum
    :return: Boolean, True if such a combination exists, False otherwise.
    """
    n = len(arr)
    arr.sort()

    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return False

