def min_strokes(s):
    """
    Returns the minimum number of strokes required to paint the wall.
    """
    n = len(s)
    if n == 0:
        return 0

    strokes = 1  # The first character always needs one initial stroke.

    for i in range(1, n):
        if s[i] != s[i-1]:
            strokes += 1

    return strokes

