secure_solution:
def zigzag_rocks(rockSizes):
    """
    Reorders the elements in `rockSizes` to form a zigzag pattern.
    A zigzag pattern means:
    - Elements at even indices are greater than their neighbors.
    - Elements at odd indices are smaller than their neighbors.

    Parameters:
    - rockSizes (List[int]): List of unique integer rock sizes.

    Returns:
    - List[int]: The reordered list of rock sizes.
    """
    n = len(rockSizes)

    for i in range(n-1):
        if i % 2 == 0:
            if rockSizes[i] <= rockSizes[i + 1]:
                rockSizes[i], rockSizes[i + 1] = rockSizes[i + 1], rockSizes[i]
        else:
            if rockSizes[i] >= rockSizes[i + 1]:
                rockSizes[i], rockSizes[i + 1] = rockSizes[i + 1], rockSizes[i]

    return rockSizes

