def schedule_meetings(n, m, k, conflicts):
    from collections import defaultdict

    if k > (n - 1):
        return "NO", []

    conflict_set = set((min(a, b), max(a, b)) for a, b in conflicts)
    # Initialize a list to maintain each employee's meeting count
    meeting_count = [0] * n

    meetings = []
    for i in range(1, n + 1):
