def min_energy_cost(n, grid):
    """
    Returns the minimum energy cost required to reach the bottom-right cell from the top-left cell.
    """
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = grid[0][0]

    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + grid[i][0]
        dp[0][i] = dp[0][i-1] + grid[0][i]

    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[n-1][n-1]

