from collections import defaultdict, deque

def circular_seating(n, m, friendships):
    if m < n-1:
        return -1

    adj = defaultdict(list)
    for a, b in friendships:
        adj[a].append(b)
        adj[b].append(a)

    if any(len(adj[x]) > 2 for x in adj):
        return -1

    degrees = {x: len(adj[x]) for x in adj}
    end_points = [x for x in degrees if degrees[x] == 1]
    if len(end_points) != 2:
        return -1

    queue = deque([end_points[0]])
    visited = set()
    order = []

    while queue:
        node = queue.popleft()
        if node in visited:
            continue
        visited.add(node)
        order.append(node)
        for neighbor in adj[node]:
            adj[neighbor].remove(node)
            queue.append(neighbor)

    if len(order) == n:
        return order
    else:
        return -1

