def find_pair_with_sum(n, arr, target):
    """
    Given an array of integers and a target sum, returns a pair of distinct elements whose sum is equal to the target sum.
    If such a pair exists, returns the pair in ascending order; otherwise returns "No pair found".
    """
    seen = set()
    for number in arr:
        complement = target - number
        if complement in seen:
            return (min(number, complement), max(number, complement))
        seen.add(number)
    return "No pair found"

