def find_pairs_with_difference(arr, k):
    """
    Returns the number of distinct pairs (arr[i], arr[j]) such that i != j
    and the absolute difference between arr[i] and arr[j] is equal to k.
    """
    seen = set()
    pairs = set()

    for num in arr:
        if num + k in seen:
            pairs.add((num, num + k))
        if num - k in seen:
            pairs.add((num - k, num))
        seen.add(num)

    return len(pairs)

