def longest_subarray_with_sum(nums, target):
    """
    Returns the length of the longest subarray whose sum is equal to the given target.
    """
    prefix_sum = 0
    max_length = 0
    prefix_sum_indices = {0: -1}

    for i, num in enumerate(nums):
        prefix_sum += num

        if prefix_sum - target in prefix_sum_indices:
            max_length = max(max_length, i - prefix_sum_indices[prefix_sum - target])

        if prefix_sum not in prefix_sum_indices:
            prefix_sum_indices[prefix_sum] = i

