def max_product_after_swaps(T, test_cases):
    results = []
    for i in range(T):
        N = test_cases[i][0]
        A = test_cases[i][1]
        if N < 2:
            results.append(0)  # No possible swaps
            continue
        # Find two maximum absolute values in the array
        max1, max2 = float('-inf'), float('-inf')
        min1, min2 = float('inf'), float('inf')

        for num in A:
            if num > max1:
                max2 = max1
                max1 = num
            elif num > max2:
                max2 = num

            if num < min1:
                min2 = min1
                min1 = num
            elif num < min2:
                min2 = num

        max_product = max(max1 * max2, min1 * min2)
        results.append(max_product)

    return results

