def can_find_equal_sum_subarrays(n, array):
    """
    Determines if there exist two non-overlapping subarrays with equal sum.

    :param n: Length of the array
    :param array: List of positive integers
    :return: "YES" if such subarrays exist, otherwise "NO"
    """
    for length in range(1, n//2 + 1):
        sums_seen = {}
        for start in range(n - length + 1):
            subarray_sum = sum(array[start:start + length])

            if subarray_sum in sums_seen:
                if start - sums_seen[subarray_sum] >= length:
                    return "YES"
            else:
                sums_seen[subarray_sum] = start + length  # save the end of the subarray
    return "NO"

