def min_abs_diff(nums):
    total_sum = sum(nums)
    n = len(nums)
    half_sum = total_sum // 2

    dp = [False] * (half_sum + 1)
    dp[0] = True

    for num in nums:
        for j in range(half_sum, num - 1, -1):
            dp[j] = dp[j] or dp[j - num]

    for i in range(half_sum, -1, -1):
        if dp[i]:
            return total_sum - 2 * i

