def max_distinct_timestamps(log: str, k: int) -> int:
    timestamps = list(map(int, log.split(',')))
    n = len(timestamps)
    max_distinct = 0

    for i in range(n):
        seen = set()
        for j in range(i, n):
            seen.add(timestamps[j])
            if timestamps[j] - timestamps[i] <= k:
                max_distinct = max(max_distinct, len(seen))
            else:
                break

    return max_distinct

