from typing import List

def optimized_search(prices: List[int], target_price: int) -> int:
    """
    Returns the index of target_price in the sorted list prices if found, else returns -1.
    """
    low = 0
    high = len(prices) - 1

    while low <= high and target_price >= prices[low] and target_price <= prices[high]:
        if prices[low] == prices[high]:  # Avoid division by zero
            if prices[low] == target_price:
                return low if prices[low] == target_price else -1
            return -1

        pos = low + ((high - low) // (prices[high] - prices[low]) * (target_price - prices[low]))

        if pos < low or pos > high:
            return -1

        if prices[pos] == target_price:
            return pos
        if prices[pos] < target_price:
            low = pos + 1
        else:
            high = pos - 1

    return -1

