def process_queries(N, Q, A, queries):
    results = []
    for query in queries:
        parts = query.split()
        if parts[0] == '+':
            x, y = int(parts[1]), int(parts[2])
            A.extend([x] * y)
        elif parts[0] == '*':
            l, r, k = int(parts[1]), int(parts[2]), int(parts[3])
            for i in range(l-1, r):
                A[i] *= k
        elif parts[0] == '?':
