def min_bins(products, binCapacity):
    """
    Given a list of product volumes and a bin capacity,
    returns the minimum number of bins required to store all the products.
    If it's not possible, returns -1.
    """
    products.sort(reverse=True)

    bins = []

    for volume in products:
        placed = False
        for i in range(len(bins)):
            if bins[i] + volume <= binCapacity:
                bins[i] += volume
                placed = True
                break
        if not placed:
            if volume > binCapacity:
                return -1
            bins.append(volume)

    return len(bins)

