from collections import deque

def shortestPath(grid, k):
    """
    Returns the length of the shortest path from (0, 0) to (m-1, n-1) allowing at most k obstacles to be removed.
    If no such path exists, return -1.
    """
    m, n = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    if m == 1 and n == 1:
        return 0

    queue = deque([(0, 0, 0)])  # (x, y, obstacles_removed)
    visited = {(0, 0, 0)}

    steps = 0
    while queue:
        steps += 1
        for _ in range(len(queue)):
            x, y, removed = queue.popleft()

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if 0 <= nx < m and 0 <= ny < n:
                    new_removed = removed + grid[nx][ny]

                    if new_removed <= k and (nx, ny, new_removed) not in visited:
                        if nx == m - 1 and ny == n - 1:
                            return steps
                        queue.append((nx, ny, new_removed))
                        visited.add((nx, ny, new_removed))

    return -1

