def scheduler(commands):
    """
    Processes a list of scheduler commands and returns the status of tasks after all operations.
    """
    tasks = {}
    order = []

    for command in commands:
        parts = command.split()
        action = parts[0]
        task_name = parts[1]

        if action == "ADD":
            tasks[task_name] = "PENDING"
            order.append(task_name)
        elif action == "DELETE":
            if task_name in tasks:
                del tasks[task_name]
                order.remove(task_name)
        elif action == "RUN":
            if task_name in tasks and tasks[task_name] == "PENDING":
                tasks[task_name] = "RUNNING"
        elif action == "STOP":
            if task_name in tasks and tasks[task_name] == "RUNNING":
                tasks[task_name] = "PENDING"
        elif action == "COMPLETE":
            if task_name in tasks and tasks[task_name] == "RUNNING":
                tasks[task_name] = "COMPLETED"

    result = []
    seen_tasks = set()
    for task in reversed(order):
        if task not in seen_tasks:
            result.append(f"{task}: {tasks[task]}")
            seen_tasks.add(task)

    return list(reversed(result))

