            if task_name in tasks and tasks[task_name] == "RUNNING":
                tasks[task_name] = "COMPLETED"

    result = []
    seen_tasks = set()
    for task in reversed(order):
        if task not in seen_tasks:
            result.append(f"{task}: {tasks[task]}")
            seen_tasks.add(task)

    return list(reversed(result))

