def find_smiling_intervals(arr):
    """
    Returns the count of "smiling intervals" in the array.
    A "smiling interval" is defined as a contiguous subarray where the first element is smaller than the last element.
    """
    count = 0
    n = len(arr)

    for i in range(n):
        for j in range(i+1, n):
            if arr[i] < arr[j]:
                count += 1

    return count

