def unobstructed_view_buildings(arr):
    """
    Returns the indices of buildings that have an unobstructed view of the sunset.
    Only buildings that have no taller buildings to their right have an unobstructed view.
    """
    n = len(arr)
    if n == 0:
        return []

    result = []
    max_height = float('-inf')

    for i in reversed(range(n)):
        if arr[i] > max_height:
            result.append(i)
            max_height = arr[i]

    return sorted(result)

