def longest_contiguous_subsequence(n, sequence):
    if n == 0:
        return 0

    longest_len = 1
    current_len = 1
    increasing = None  # None if we haven't started determining the trend yet

    for i in range(1, n):
        if sequence[i] > sequence[i - 1]:
            if increasing is None or increasing:
                current_len += 1
            else:
                current_len = 2
            increasing = True
        elif sequence[i] < sequence[i - 1]:
            if increasing is None or not increasing:
                current_len += 1
            else:
                current_len = 2
            increasing = False
        else:
            current_len = 1
            increasing = None

        longest_len = max(longest_len, current_len)

    return longest_len

