def minimum_moves_to_reach_largest(n, m, grid):
    # Create a dictionary to store the position of each number in the grid.
    position_dict = {}

    for i in range(n):
        for j in range(m):
            position_dict[grid[i][j]] = (i, j)

    # Find the position of the smallest and largest numbers in the grid.
    min_pos = position_dict[min(position_dict.keys())]
    max_pos = position_dict[max(position_dict.keys())]

    # Calculate the minimum number of moves using the Manhattan distance.
    min_moves = abs(min_pos[0] - max_pos[0]) + abs(min_pos[1] - max_pos[1])

    return min_moves

