def generate_sequence(N):
    """
    Generate a sequence of N integers such that each integer is either 1 or -1,
    and the sum of any non-empty contiguous subsequence of the sequence is not equal to 0.
    """
    sequence = []
    for i in range(N):
        if i % 2 == 0:
            sequence.append(1)
        else:
            sequence.append(-1)
    return sequence

