def generate_diamond(n):
    if n <= 0:
        return ""

    diamond = []

    for i in range(1, n+1):
        stars = ' '.join('*' * i)
        spaces = ' ' * (n - i)
        diamond.append(spaces + stars + spaces)

    for i in range(n-1, 0, -1):
        stars = ' '.join('*' * i)
        spaces = ' ' * (n - i)
        diamond.append(spaces + stars + spaces)

    return '\n'.join(diamond)

