def max_score(n, k, scores):
    dp = [0] * n

    # Compute the maximum score for each level if that level is chosen
    for i in range(n):
        # We start by taking the current level's score
        dp[i] = scores[i]
        # Then we add the maximum score achievable by choosing a previous level,
        # such that the next 'k' levels after that previous level are not chosen.
        if i > k:
            dp[i] += max(dp[:i - k])

    return max(dp)

