secure_solution:
def longest_common_substring(s1: str, s2: str) -> str:
    """
    Finds the longest common substring between two strings.
    """
    m, n = len(s1), len(s2)

    # Create a matrix to hold the lengths of the longest common suffixes
    lcsuff = [[0] * (n + 1) for _ in range(m + 1)]

    longest = 0
    end_index = 0  # ending index of the longest common substring

    # Build the lcsuff matrix in bottom-up fashion
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                lcsuff[i][j] = 0
            elif s1[i - 1] == s2[j - 1]:
                lcsuff[i][j] = lcsuff[i - 1][j - 1] + 1
                if lcsuff[i][j] > longest:
                    longest = lcsuff[i][j]
                    end_index = i
            else:
                lcsuff[i][j] = 0

    # If no common substring exists, return an empty string
    if longest == 0:
        return ""

    # The longest common substring is from index end_index-longest to end_index in s1
    return s1[end_index - longest:end_index]

